-- shared_file_facts.sql() emits the same affected-component maintenance for
-- hash and size membership at review and edition publication. Keeping one
-- generator prevents one lane or an old issued alias being forgotten.

-- Typed native literal/position closure is deliberately left to the main
-- candidate harness. Native declarations point to reported_catalog_relationships;
-- canonical position rows must point to canonical_relationship_id and must
-- not copy their literal. The harness must prove one typed owner and one
-- canonical position per reported identity in both directions, including
-- kind, field-key, and edition ancestry. No polymorphic source-owner row is
-- persisted. Relationships.sql provides candidate_relationship_integrity_problems
-- for registry/declaration/evidence/shared-hash checks; it does not substitute
-- for this native position closure.


-- Exact diagnostic evidence is separate from catalog values and external originals.
CREATE TABLE catalog_import_messages (
    message_id INTEGER PRIMARY KEY NOT NULL CHECK (message_id > 0),
    import_id INTEGER NOT NULL REFERENCES catalog_imports(import_id),
    message_order INTEGER NOT NULL CHECK (message_order >= 0),
    severity TEXT NOT NULL CHECK (severity IN ('warning', 'error')),
    code TEXT NOT NULL,
    message TEXT NOT NULL,
    record_kind TEXT,
    record_name TEXT,
    field_name TEXT,
    offending_text TEXT,
    edition_id INTEGER REFERENCES catalog_editions(edition_id),
    source_file_id INTEGER NOT NULL REFERENCES catalog_source_files(source_file_id),
    reading_rules_id INTEGER NOT NULL REFERENCES catalog_reading_rules(reading_rules_id),
    excerpt BLOB,
    source_view TEXT CHECK (source_view IN ('retained_original_bytes', 'transport_decoded_xml_bytes')),
    excerpt_source_start INTEGER CHECK (excerpt_source_start >= 0),
    excerpt_problem_start INTEGER,
    excerpt_problem_end INTEGER,
    source_problem_start INTEGER,
    source_problem_end INTEGER,
    original_problem_start INTEGER,
    original_problem_end INTEGER,
    line INTEGER CHECK (line > 0),
    column INTEGER CHECK (column > 0),
    location_view TEXT CHECK (location_view IN ('retained_original_text', 'transport_decoded_xml_text', 'decoded_dat_text')),
    column_convention TEXT CHECK (column_convention = 'one_based_unicode_scalar'),
    FOREIGN KEY (import_id, source_file_id, reading_rules_id)
        REFERENCES catalog_imports(import_id, source_file_id, reading_rules_id),
    UNIQUE (import_id, message_order),
    UNIQUE (message_id, edition_id),
    CHECK ((excerpt IS NULL AND excerpt_source_start IS NULL) OR
        (excerpt IS NOT NULL AND excerpt_source_start IS NOT NULL AND source_view IS NOT NULL)),
    CHECK ((excerpt_problem_start IS NULL AND excerpt_problem_end IS NULL) OR
        (excerpt_problem_start IS NOT NULL AND excerpt_problem_end IS NOT NULL AND excerpt IS NOT NULL
         AND 0 <= excerpt_problem_start AND excerpt_problem_start <= excerpt_problem_end AND excerpt_problem_end <= length(excerpt))),
    CHECK ((source_problem_start IS NULL AND source_problem_end IS NULL) OR
        (source_problem_start IS NOT NULL AND source_problem_end IS NOT NULL AND source_view IS NOT NULL
         AND 0 <= source_problem_start AND source_problem_start <= source_problem_end)),
    CHECK ((original_problem_start IS NULL AND original_problem_end IS NULL) OR
        (original_problem_start IS NOT NULL AND original_problem_end IS NOT NULL
         AND 0 <= original_problem_start AND original_problem_start <= original_problem_end)),
    CHECK ((location_view IS NULL AND column_convention IS NULL) OR
        (location_view IS NOT NULL AND column_convention IS NOT NULL))
) STRICT;

CREATE TABLE catalog_import_message_elements (
    message_id INTEGER NOT NULL,
    source_element_id INTEGER NOT NULL,
    edition_id INTEGER NOT NULL,
    role TEXT NOT NULL CHECK (role IN ('primary', 'related')),
    PRIMARY KEY (message_id, source_element_id, role),
    FOREIGN KEY (message_id, edition_id) REFERENCES catalog_import_messages(message_id, edition_id),
    FOREIGN KEY (source_element_id, edition_id) REFERENCES catalog_source_elements(source_element_id, edition_id)
) STRICT, WITHOUT ROWID;

CREATE INDEX catalog_import_message_elements_by_owner
    ON catalog_import_message_elements(source_element_id,message_id);
CREATE INDEX catalog_import_message_elements_by_edition
    ON catalog_import_message_elements(edition_id,message_id);

CREATE TABLE catalog_import_message_external_evidence (
    message_id INTEGER NOT NULL REFERENCES catalog_import_messages(message_id),
    compared_source_element_id INTEGER NOT NULL,
    target_edition_id INTEGER NOT NULL REFERENCES published_catalog_editions(edition_id),
    evidence_role TEXT NOT NULL CHECK (evidence_role IN ('conflicting_candidate', 'comparison_reference')),
    PRIMARY KEY (message_id, compared_source_element_id, evidence_role),
    FOREIGN KEY (compared_source_element_id, target_edition_id)
        REFERENCES catalog_source_elements(source_element_id, edition_id)
) STRICT, WITHOUT ROWID;

CREATE VIEW candidate_message_integrity_problems AS
SELECT 'message_import_edition' AS problem, message.message_id AS owner_id, coalesce(message.edition_id,run.edition_id) AS edition_id
FROM catalog_import_messages AS message JOIN catalog_imports AS run USING (import_id)
WHERE message.edition_id IS NOT run.edition_id
UNION ALL
SELECT 'message_original_bounds', message.message_id, message.edition_id
FROM catalog_import_messages AS message JOIN catalog_source_files AS source USING (source_file_id)
WHERE message.original_problem_end > source.byte_length
    OR (message.source_view = 'retained_original_bytes' AND
        (message.source_problem_end > source.byte_length OR length(message.excerpt) > source.byte_length - message.excerpt_source_start))
UNION ALL
SELECT 'message_decoded_bounds',message.message_id,message.edition_id
FROM catalog_import_messages AS message LEFT JOIN catalog_decoded_xml_views AS view USING(source_file_id)
WHERE message.source_view='transport_decoded_xml_bytes'
AND (message.source_problem_end IS NOT NULL OR message.excerpt_source_start IS NOT NULL)
AND (view.source_file_id IS NULL OR message.source_problem_end > view.byte_length OR length(message.excerpt) > view.byte_length-message.excerpt_source_start)
UNION ALL
SELECT 'message_highlight_mapping',message.message_id,message.edition_id FROM catalog_import_messages AS message WHERE (message.excerpt_source_start IS NOT NULL AND (
        (coalesce(message.source_problem_start,CASE WHEN message.source_view='retained_original_bytes' THEN message.original_problem_start END) IS NULL AND (message.excerpt_problem_start IS NOT NULL OR message.excerpt_problem_end IS NOT NULL)) OR
        (coalesce(message.source_problem_start,CASE WHEN message.source_view='retained_original_bytes' THEN message.original_problem_start END) IS NOT NULL AND (
            (coalesce(message.source_problem_start,CASE WHEN message.source_view='retained_original_bytes' THEN message.original_problem_start END)>=message.excerpt_source_start AND coalesce(message.source_problem_end,CASE WHEN message.source_view='retained_original_bytes' THEN message.original_problem_end END)-message.excerpt_source_start<=length(message.excerpt) AND (message.excerpt_problem_start IS NOT coalesce(message.source_problem_start,CASE WHEN message.source_view='retained_original_bytes' THEN message.original_problem_start END)-message.excerpt_source_start OR message.excerpt_problem_end IS NOT coalesce(message.source_problem_end,CASE WHEN message.source_view='retained_original_bytes' THEN message.original_problem_end END)-message.excerpt_source_start)) OR
            ((coalesce(message.source_problem_start,CASE WHEN message.source_view='retained_original_bytes' THEN message.original_problem_start END)<message.excerpt_source_start OR coalesce(message.source_problem_end,CASE WHEN message.source_view='retained_original_bytes' THEN message.original_problem_end END)-message.excerpt_source_start>length(message.excerpt)) AND (message.excerpt_problem_start IS NOT NULL OR message.excerpt_problem_end IS NOT NULL))
        ))
    )) UNION ALL SELECT 'message_coordinate_views',message.message_id,message.edition_id FROM catalog_import_messages AS message WHERE (message.source_view='retained_original_bytes'
        AND message.source_problem_start IS NOT NULL
        AND message.original_problem_start IS NOT NULL
        AND (message.source_problem_start IS NOT message.original_problem_start
             OR message.source_problem_end IS NOT message.original_problem_end))
UNION ALL
SELECT 'external_evidence_is_incoming', evidence.message_id, message.edition_id
FROM catalog_import_message_external_evidence AS evidence JOIN catalog_import_messages AS message USING (message_id)
WHERE evidence.target_edition_id IS message.edition_id;

CREATE TRIGGER candidate_message_coordinates_insert
        BEFORE INSERT ON catalog_import_messages
        WHEN (NEW.excerpt_source_start IS NOT NULL AND (
        (coalesce(NEW.source_problem_start,CASE WHEN NEW.source_view='retained_original_bytes' THEN NEW.original_problem_start END) IS NULL AND (NEW.excerpt_problem_start IS NOT NULL OR NEW.excerpt_problem_end IS NOT NULL)) OR
        (coalesce(NEW.source_problem_start,CASE WHEN NEW.source_view='retained_original_bytes' THEN NEW.original_problem_start END) IS NOT NULL AND (
            (coalesce(NEW.source_problem_start,CASE WHEN NEW.source_view='retained_original_bytes' THEN NEW.original_problem_start END)>=NEW.excerpt_source_start AND coalesce(NEW.source_problem_end,CASE WHEN NEW.source_view='retained_original_bytes' THEN NEW.original_problem_end END)-NEW.excerpt_source_start<=length(NEW.excerpt) AND (NEW.excerpt_problem_start IS NOT coalesce(NEW.source_problem_start,CASE WHEN NEW.source_view='retained_original_bytes' THEN NEW.original_problem_start END)-NEW.excerpt_source_start OR NEW.excerpt_problem_end IS NOT coalesce(NEW.source_problem_end,CASE WHEN NEW.source_view='retained_original_bytes' THEN NEW.original_problem_end END)-NEW.excerpt_source_start)) OR
            ((coalesce(NEW.source_problem_start,CASE WHEN NEW.source_view='retained_original_bytes' THEN NEW.original_problem_start END)<NEW.excerpt_source_start OR coalesce(NEW.source_problem_end,CASE WHEN NEW.source_view='retained_original_bytes' THEN NEW.original_problem_end END)-NEW.excerpt_source_start>length(NEW.excerpt)) AND (NEW.excerpt_problem_start IS NOT NULL OR NEW.excerpt_problem_end IS NOT NULL))
        ))
    )) OR (NEW.source_view='retained_original_bytes'
        AND NEW.source_problem_start IS NOT NULL
        AND NEW.original_problem_start IS NOT NULL
        AND (NEW.source_problem_start IS NOT NEW.original_problem_start
             OR NEW.source_problem_end IS NOT NEW.original_problem_end))
        BEGIN SELECT RAISE(ABORT,'diagnostic coordinates do not match their source views'); END;
CREATE TRIGGER candidate_message_coordinates_update
        BEFORE UPDATE ON catalog_import_messages
        WHEN (NEW.excerpt_source_start IS NOT NULL AND (
        (coalesce(NEW.source_problem_start,CASE WHEN NEW.source_view='retained_original_bytes' THEN NEW.original_problem_start END) IS NULL AND (NEW.excerpt_problem_start IS NOT NULL OR NEW.excerpt_problem_end IS NOT NULL)) OR
        (coalesce(NEW.source_problem_start,CASE WHEN NEW.source_view='retained_original_bytes' THEN NEW.original_problem_start END) IS NOT NULL AND (
            (coalesce(NEW.source_problem_start,CASE WHEN NEW.source_view='retained_original_bytes' THEN NEW.original_problem_start END)>=NEW.excerpt_source_start AND coalesce(NEW.source_problem_end,CASE WHEN NEW.source_view='retained_original_bytes' THEN NEW.original_problem_end END)-NEW.excerpt_source_start<=length(NEW.excerpt) AND (NEW.excerpt_problem_start IS NOT coalesce(NEW.source_problem_start,CASE WHEN NEW.source_view='retained_original_bytes' THEN NEW.original_problem_start END)-NEW.excerpt_source_start OR NEW.excerpt_problem_end IS NOT coalesce(NEW.source_problem_end,CASE WHEN NEW.source_view='retained_original_bytes' THEN NEW.original_problem_end END)-NEW.excerpt_source_start)) OR
            ((coalesce(NEW.source_problem_start,CASE WHEN NEW.source_view='retained_original_bytes' THEN NEW.original_problem_start END)<NEW.excerpt_source_start OR coalesce(NEW.source_problem_end,CASE WHEN NEW.source_view='retained_original_bytes' THEN NEW.original_problem_end END)-NEW.excerpt_source_start>length(NEW.excerpt)) AND (NEW.excerpt_problem_start IS NOT NULL OR NEW.excerpt_problem_end IS NOT NULL))
        ))
    )) OR (NEW.source_view='retained_original_bytes'
        AND NEW.source_problem_start IS NOT NULL
        AND NEW.original_problem_start IS NOT NULL
        AND (NEW.source_problem_start IS NOT NEW.original_problem_start
             OR NEW.source_problem_end IS NOT NEW.original_problem_end))
        BEGIN SELECT RAISE(ABORT,'diagnostic coordinates do not match their source views'); END;

CREATE TRIGGER candidate_message_ancestry_insert BEFORE INSERT ON catalog_import_messages
WHEN NOT EXISTS (SELECT 1 FROM catalog_imports WHERE import_id=NEW.import_id AND edition_id IS NEW.edition_id)
BEGIN SELECT RAISE(ABORT,'message must use the actual import edition'); END;

CREATE TRIGGER candidate_import_message_reverse BEFORE UPDATE ON catalog_imports
WHEN EXISTS(SELECT 1 FROM catalog_import_messages AS message WHERE message.import_id=OLD.import_id AND
    (message.edition_id IS NOT NEW.edition_id OR message.source_file_id<>NEW.source_file_id OR message.reading_rules_id<>NEW.reading_rules_id))
BEGIN SELECT RAISE(ABORT,'import rewrite would invalidate existing messages'); END;
CREATE TRIGGER candidate_message_ancestry_update BEFORE UPDATE ON catalog_import_messages
WHEN NOT EXISTS (SELECT 1 FROM catalog_imports WHERE import_id=NEW.import_id AND edition_id IS NEW.edition_id)
BEGIN SELECT RAISE(ABORT,'message must use the actual import edition'); END;


-- Native MAME child/PCDATA cardinality and strict content-sequence audit.
-- This fragment is included explicitly by the schema-candidate assembler.
-- It adds diagnostics only; publication integration belongs to the assembler.
-- Empty #PCDATA is valid for description/year/manufacturer/ramoption text.

CREATE VIEW candidate_mame_cardinality_problems AS
WITH strict_machines AS (
    SELECT machine.set_id AS owner_id
    FROM mame_machines AS machine
    JOIN catalog_source_elements AS element
      ON element.source_element_id=machine.set_id
    JOIN catalog_editions AS edition ON edition.edition_id=element.edition_id
    JOIN catalog_reading_rules AS rules ON rules.reading_rules_id=edition.reading_rules_id
    WHERE rules.format_family='mame' AND rules.dialect='strict-dtd'
),
machine_children AS (
    SELECT text.machine_id AS owner_id,text.source_order,
           CASE text.field_kind
             WHEN 'description' THEN 0
             WHEN 'year' THEN 1
             WHEN 'manufacturer' THEN 2
           END AS content_rank
    FROM mame_machine_text_elements AS text
    JOIN strict_machines AS strict ON strict.owner_id=text.machine_id
    UNION ALL SELECT child.machine_id,child.source_order,3 FROM mame_bios_sets AS child JOIN strict_machines AS strict ON strict.owner_id=child.machine_id
    UNION ALL SELECT child.machine_id,child.source_order,4 FROM mame_roms AS child JOIN strict_machines AS strict ON strict.owner_id=child.machine_id
    UNION ALL SELECT child.machine_id,child.source_order,5 FROM mame_disks AS child JOIN strict_machines AS strict ON strict.owner_id=child.machine_id
    UNION ALL SELECT child.machine_id,child.source_order,6 FROM mame_device_references AS child JOIN strict_machines AS strict ON strict.owner_id=child.machine_id
    UNION ALL SELECT child.machine_id,child.source_order,7 FROM mame_samples AS child JOIN strict_machines AS strict ON strict.owner_id=child.machine_id
    UNION ALL SELECT child.machine_id,child.source_order,8 FROM mame_chips AS child JOIN strict_machines AS strict ON strict.owner_id=child.machine_id
    UNION ALL SELECT child.machine_id,child.source_order,9 FROM mame_displays AS child JOIN strict_machines AS strict ON strict.owner_id=child.machine_id
    UNION ALL SELECT child.machine_id,child.source_order,10 FROM mame_sound AS child JOIN strict_machines AS strict ON strict.owner_id=child.machine_id
    UNION ALL SELECT child.machine_id,child.source_order,11 FROM mame_inputs AS child JOIN strict_machines AS strict ON strict.owner_id=child.machine_id
    UNION ALL SELECT child.machine_id,child.source_order,12 FROM mame_switches AS child JOIN strict_machines AS strict ON strict.owner_id=child.machine_id WHERE child.kind='dipswitch'
    UNION ALL SELECT child.machine_id,child.source_order,13 FROM mame_switches AS child JOIN strict_machines AS strict ON strict.owner_id=child.machine_id WHERE child.kind='configuration'
    UNION ALL SELECT child.machine_id,child.source_order,14 FROM mame_ports AS child JOIN strict_machines AS strict ON strict.owner_id=child.machine_id
    UNION ALL SELECT child.machine_id,child.source_order,15 FROM mame_adjusters AS child JOIN strict_machines AS strict ON strict.owner_id=child.machine_id
    UNION ALL SELECT child.machine_id,child.source_order,16 FROM mame_drivers AS child JOIN strict_machines AS strict ON strict.owner_id=child.machine_id
    UNION ALL SELECT child.machine_id,child.source_order,17 FROM mame_features AS child JOIN strict_machines AS strict ON strict.owner_id=child.machine_id
    UNION ALL SELECT child.machine_id,child.source_order,18 FROM mame_devices AS child JOIN strict_machines AS strict ON strict.owner_id=child.machine_id
    UNION ALL SELECT child.machine_id,child.source_order,19 FROM mame_slots AS child JOIN strict_machines AS strict ON strict.owner_id=child.machine_id
    UNION ALL SELECT child.machine_id,child.source_order,20 FROM mame_softwarelist_references AS child JOIN strict_machines AS strict ON strict.owner_id=child.machine_id
    UNION ALL SELECT child.machine_id,child.source_order,21 FROM mame_ram_options AS child JOIN strict_machines AS strict ON strict.owner_id=child.machine_id
),
strict_machine_sequence AS (
    SELECT owner_id
    FROM (
        SELECT owner_id,content_rank,
               max(content_rank) OVER (
                   PARTITION BY owner_id ORDER BY source_order
                   ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING
               ) AS prior_max_rank
        FROM machine_children
    ) AS ordered
    WHERE content_rank<prior_max_rank
    GROUP BY owner_id
),
strict_switches AS (
    SELECT switch.source_element_id AS owner_id
    FROM mame_switches AS switch
    JOIN catalog_source_elements AS element
      ON element.source_element_id=switch.source_element_id
    JOIN catalog_editions AS edition ON edition.edition_id=element.edition_id
    JOIN catalog_reading_rules AS rules ON rules.reading_rules_id=edition.reading_rules_id
    WHERE rules.format_family='mame' AND rules.dialect='strict-dtd'
),
switch_children AS (
    SELECT condition.switch_id AS owner_id,condition.source_order,0 AS content_rank
    FROM mame_switch_conditions AS condition
    JOIN strict_switches AS strict ON strict.owner_id=condition.switch_id
    UNION ALL
    SELECT location.switch_id,location.source_order,1
    FROM mame_switch_locations AS location
    JOIN strict_switches AS strict ON strict.owner_id=location.switch_id
    UNION ALL
    SELECT value.switch_id,value.source_order,2
    FROM mame_switch_values AS value
    JOIN strict_switches AS strict ON strict.owner_id=value.switch_id
),
strict_switch_sequence AS (
    SELECT owner_id
    FROM (
        SELECT owner_id,content_rank,
               max(content_rank) OVER (
                   PARTITION BY owner_id ORDER BY source_order
                   ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING
               ) AS prior_max_rank
        FROM switch_children
    ) AS ordered
    WHERE content_rank<prior_max_rank
    GROUP BY owner_id
),
strict_devices AS (
    SELECT device.source_element_id AS owner_id,element.edition_id
    FROM mame_devices AS device
    JOIN catalog_source_elements AS element
      ON element.source_element_id=device.source_element_id
    JOIN catalog_editions AS edition ON edition.edition_id=element.edition_id
    JOIN catalog_reading_rules AS rules ON rules.reading_rules_id=edition.reading_rules_id
    WHERE rules.format_family='mame' AND rules.dialect='strict-dtd'
)
SELECT 'mame_root_requires_machine' AS problem,
       document.edition_id AS owner_id,
       document.edition_id AS edition_id
FROM mame_documents AS document
LEFT JOIN catalog_set_groups AS root_group
  ON root_group.edition_id=document.edition_id
 AND root_group.group_kind='root'
LEFT JOIN catalog_sets AS machine_set
  ON machine_set.set_group_id=root_group.set_group_id
LEFT JOIN mame_machines AS machine
  ON machine.set_id=machine_set.set_id
GROUP BY document.edition_id
HAVING count(machine.set_id)=0

UNION ALL

-- ROM size is required by the pinned DTD but intentionally nullable in the
-- shared projection because observed compatibility accepts its absence.
SELECT 'strict_rom_requires_size',
       rom.media_entry_id,
       element.edition_id
FROM mame_roms AS rom
JOIN catalog_source_elements AS element
  ON element.source_element_id=rom.media_entry_id
JOIN catalog_editions AS edition ON edition.edition_id=element.edition_id
JOIN catalog_reading_rules AS rules ON rules.reading_rules_id=edition.reading_rules_id
WHERE rules.format_family='mame'
  AND rules.dialect='strict-dtd'
  AND rom.size_text IS NULL

UNION ALL

SELECT 'machine_requires_description',
       machine.set_id,
       element.edition_id
FROM mame_machines AS machine
JOIN catalog_source_elements AS element
  ON element.source_element_id=machine.set_id
LEFT JOIN mame_machine_text_elements AS description
  ON description.machine_id=machine.set_id
 AND description.field_kind='description'
GROUP BY machine.set_id,element.edition_id
HAVING count(description.source_element_id)=0

UNION ALL

-- The DTD's sequence is dialect-specific; observed compatibility retains the
-- parser's accepted source order.
SELECT 'strict_machine_child_sequence',
       machine.set_id,
       element.edition_id
FROM strict_machine_sequence AS violation
JOIN mame_machines AS machine ON machine.set_id=violation.owner_id
JOIN catalog_source_elements AS element
  ON element.source_element_id=machine.set_id

UNION ALL

SELECT 'strict_switch_child_sequence',
       switch.source_element_id,
       element.edition_id
FROM strict_switch_sequence AS violation
JOIN mame_switches AS switch ON switch.source_element_id=violation.owner_id
JOIN catalog_source_elements AS element
  ON element.source_element_id=switch.source_element_id

UNION ALL

SELECT 'strict_device_child_sequence',
       strict.owner_id,
       strict.edition_id
FROM strict_devices AS strict
WHERE EXISTS (
      SELECT 1
      FROM mame_device_instances AS instance
      JOIN mame_device_extensions AS extension
        ON extension.device_id=strict.owner_id
       AND extension.source_order<instance.source_order
      WHERE instance.device_id=strict.owner_id
  );


-- Native software child/PCDATA cardinalities not expressible by row keys.
-- Parser-compatible cardinalities are intentional: plural wrappers may be
-- empty; lists need a title; title description/year/publisher are required
-- but may be empty; notes are optional singletons; parts, areas, switches,
-- and their recognized children may be empty. The importer retains other
-- children as extensions, so this view does not reject them as DTD violations.
CREATE VIEW candidate_software_cardinality_problems AS
SELECT 'software_list_without_title' AS problem,
       list.set_group_id AS owner_id,
       groups.edition_id AS edition_id
FROM software_lists AS list
JOIN catalog_set_groups AS groups USING (set_group_id)
WHERE NOT EXISTS (
    SELECT 1
    FROM catalog_sets AS set_entry
    JOIN software_titles AS title ON title.set_id = set_entry.set_id
    WHERE set_entry.set_group_id = list.set_group_id
)
UNION ALL
SELECT 'software_title_required_text_missing',
       title.set_id,
       groups.edition_id
FROM software_titles AS title
JOIN catalog_sets AS set_entry ON set_entry.set_id = title.set_id
JOIN catalog_set_groups AS groups USING (set_group_id)
WHERE (SELECT count(*) FROM software_title_text_elements AS text
       WHERE text.set_id = title.set_id AND text.field_kind = 0) <> 1
   OR (SELECT count(*) FROM software_title_text_elements AS text
       WHERE text.set_id = title.set_id AND text.field_kind = 1) <> 1
   OR (SELECT count(*) FROM software_title_text_elements AS text
       WHERE text.set_id = title.set_id AND text.field_kind = 2) <> 1
UNION ALL
SELECT 'software_area_subtype_closure',
       area.area_id,
       coalesce(parent_element.edition_id, area_element.edition_id)
FROM software_areas AS area
LEFT JOIN catalog_source_elements AS parent_element
  ON parent_element.source_element_id = area.part_id
LEFT JOIN catalog_source_elements AS area_element
  ON area_element.source_element_id = area.area_id
WHERE (area.kind = 'data'
       AND ((SELECT count(*) FROM software_data_areas AS data
             WHERE data.area_id = area.area_id) <> 1
         OR (SELECT count(*) FROM software_disk_areas AS disk
             WHERE disk.area_id = area.area_id) <> 0))
   OR (area.kind = 'disk'
       AND ((SELECT count(*) FROM software_disk_areas AS disk
             WHERE disk.area_id = area.area_id) <> 1
         OR (SELECT count(*) FROM software_data_areas AS data
             WHERE data.area_id = area.area_id) <> 0));


-- Native child cardinality not already represented by the family integrity
-- view or typed uniqueness constraints. The parent assembler includes this
-- report in the publication gate after loading native fragments.
CREATE VIEW candidate_logiqx_cmp_cardinality_problems AS
SELECT 'cmp_requires_at_least_one_set' AS problem,
       document.edition_id AS owner_id,
       document.edition_id AS edition_id
FROM clrmamepro_documents AS document
WHERE NOT EXISTS (
    SELECT 1
    FROM catalog_sets AS placement
    JOIN catalog_set_groups AS root USING (set_group_id)
    JOIN clrmamepro_sets AS native USING (set_id)
    WHERE root.set_group_id = document.set_group_id
      AND root.edition_id = document.edition_id
);


-- Additional No-Intro child/field cardinality checks not already covered by
-- candidate_no_intro_integrity_problems. Main's assembler discovers this view
-- by its _cardinality_problems suffix and adds it to candidate publication.
-- Parent edition is resolved through the actual game/set-group ancestry.
CREATE VIEW candidate_no_intro_cardinality_problems AS
WITH required(field_kind) AS (VALUES ('size'),('crc'),('md5'),('sha1')),
first_games AS (
    SELECT set_row.set_group_id, MIN(set_row.source_order) AS first_game_order
    FROM catalog_sets AS set_row
    JOIN no_intro_dat_games AS game ON game.set_id=set_row.set_id
    GROUP BY set_row.set_group_id
),
strict_header_events AS (
    SELECT header.header_id,
           field.source_order,
           CASE field.field_kind
               WHEN 'id' THEN 0
               WHEN 'name' THEN 1
               WHEN 'description' THEN 2
               WHEN 'version' THEN 3
               WHEN 'date' THEN 4
               WHEN 'author' THEN 5
               WHEN 'homepage' THEN 6
               WHEN 'url' THEN 7
               WHEN 'trademarks' THEN CASE rules.dialect
                   WHEN 'no-intro-dat-v4-strict' THEN 8 END
               WHEN 'piracy' THEN CASE rules.dialect
                   WHEN 'no-intro-dat-v4-strict' THEN 9 END
               WHEN 'subset' THEN CASE rules.dialect
                   WHEN 'no-intro-dat-v3-strict' THEN 8 ELSE 10 END
           END AS child_rank
    FROM no_intro_dat_headers AS header
    JOIN catalog_set_groups AS group_row USING(set_group_id)
    JOIN catalog_editions AS edition USING(edition_id)
    JOIN catalog_reading_rules AS rules USING(reading_rules_id)
    JOIN no_intro_dat_header_text_children AS field USING(header_id)
    WHERE rules.dialect IN ('no-intro-dat-v3-strict','no-intro-dat-v4-strict')
    UNION ALL
    SELECT header.header_id,
           option_row.source_order,
           CASE rules.dialect
               WHEN 'no-intro-dat-v3-strict' THEN 9
               ELSE 11
           END AS child_rank
    FROM no_intro_dat_headers AS header
    JOIN catalog_set_groups AS group_row USING(set_group_id)
    JOIN catalog_editions AS edition USING(edition_id)
    JOIN catalog_reading_rules AS rules USING(reading_rules_id)
    JOIN no_intro_dat_clrmamepro_options AS option_row USING(header_id)
    WHERE rules.dialect IN ('no-intro-dat-v3-strict','no-intro-dat-v4-strict')
    UNION ALL
    SELECT header.header_id,
           option_row.source_order,
           CASE rules.dialect
               WHEN 'no-intro-dat-v3-strict' THEN 10
               ELSE 12
           END AS child_rank
    FROM no_intro_dat_headers AS header
    JOIN catalog_set_groups AS group_row USING(set_group_id)
    JOIN catalog_editions AS edition USING(edition_id)
    JOIN catalog_reading_rules AS rules USING(reading_rules_id)
    JOIN no_intro_dat_romcenter_options AS option_row USING(header_id)
    WHERE rules.dialect IN ('no-intro-dat-v3-strict','no-intro-dat-v4-strict')
),
strict_header_order AS (
    SELECT header_id, source_order, child_rank,
           MAX(child_rank) OVER (
               PARTITION BY header_id ORDER BY source_order
               ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING
           ) AS previous_max_rank
    FROM strict_header_events
    WHERE child_rank IS NOT NULL
),
strict_game_events AS (
    SELECT game.set_id, description.source_order, 1 AS child_rank
    FROM no_intro_dat_games AS game
    JOIN no_intro_dat_game_descriptions AS description USING(set_id)
    JOIN catalog_sets AS set_row ON set_row.set_id=game.set_id
    JOIN catalog_set_groups AS group_row USING(set_group_id)
    JOIN catalog_editions AS edition USING(edition_id)
    JOIN catalog_reading_rules AS rules USING(reading_rules_id)
    WHERE rules.dialect IN ('no-intro-dat-v3-strict','no-intro-dat-v4-strict')
    UNION ALL
    SELECT game.set_id, rom.source_order, 2 AS child_rank
    FROM no_intro_dat_games AS game
    JOIN no_intro_dat_rom_claims AS rom USING(set_id)
    JOIN catalog_sets AS set_row ON set_row.set_id=game.set_id
    JOIN catalog_set_groups AS group_row USING(set_group_id)
    JOIN catalog_editions AS edition USING(edition_id)
    JOIN catalog_reading_rules AS rules USING(reading_rules_id)
    WHERE rules.dialect IN ('no-intro-dat-v3-strict','no-intro-dat-v4-strict')
    UNION ALL
    SELECT game.set_id, category.source_order, 0 AS child_rank
    FROM no_intro_dat_games AS game
    JOIN no_intro_dat_categories AS category USING(set_id)
    JOIN catalog_sets AS set_row ON set_row.set_id=game.set_id
    JOIN catalog_set_groups AS group_row USING(set_group_id)
    JOIN catalog_editions AS edition USING(edition_id)
    JOIN catalog_reading_rules AS rules USING(reading_rules_id)
    WHERE rules.dialect IN ('no-intro-dat-v3-strict','no-intro-dat-v4-strict')
    UNION ALL
    SELECT game.set_id, release.source_order, 3 AS child_rank
    FROM no_intro_dat_games AS game
    JOIN no_intro_dat_releases AS release USING(set_id)
    JOIN catalog_sets AS set_row ON set_row.set_id=game.set_id
    JOIN catalog_set_groups AS group_row USING(set_group_id)
    JOIN catalog_editions AS edition USING(edition_id)
    JOIN catalog_reading_rules AS rules USING(reading_rules_id)
    WHERE rules.dialect IN ('no-intro-dat-v3-strict','no-intro-dat-v4-strict')
),
strict_game_order AS (
    SELECT set_id, source_order, child_rank,
           MAX(child_rank) OVER (
               PARTITION BY set_id ORDER BY source_order
               ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING
           ) AS previous_max_rank
    FROM strict_game_events
)
SELECT 'dat_strict_rom_field_missing:' || required.field_kind AS problem,
       rom.media_entry_id AS owner_id,
       group_row.edition_id AS edition_id
FROM no_intro_dat_rom_claims AS rom
JOIN no_intro_dat_games AS game ON game.set_id=rom.set_id
JOIN catalog_sets AS set_row ON set_row.set_id=game.set_id
JOIN catalog_set_groups AS group_row ON group_row.set_group_id=set_row.set_group_id
JOIN no_intro_dat_documents AS document ON document.edition_id=group_row.edition_id
JOIN catalog_editions AS edition ON edition.edition_id=document.edition_id
JOIN catalog_reading_rules AS rules ON rules.reading_rules_id=edition.reading_rules_id
CROSS JOIN required
WHERE rules.format_family='no_intro_dat'
  AND rules.dialect IN ('no-intro-dat-v3-strict','no-intro-dat-v4-strict')
  AND NOT EXISTS (
      SELECT 1
      FROM no_intro_dat_rom_field_positions AS position
      WHERE position.media_entry_id=rom.media_entry_id
        AND position.field_kind=required.field_kind
  )
UNION ALL
SELECT 'dat_header_after_game', header.header_id, group_row.edition_id
FROM no_intro_dat_headers AS header
JOIN catalog_set_groups AS group_row USING(set_group_id)
JOIN first_games USING(set_group_id)
WHERE header.source_order >= first_games.first_game_order
UNION ALL
SELECT 'dat_strict_header_child_order', order_row.header_id, group_row.edition_id
FROM strict_header_order AS order_row
JOIN no_intro_dat_headers AS header USING(header_id)
JOIN catalog_set_groups AS group_row USING(set_group_id)
WHERE order_row.previous_max_rank > order_row.child_rank
UNION ALL
SELECT 'dat_strict_game_child_order', order_row.set_id, group_row.edition_id
FROM strict_game_order AS order_row
JOIN catalog_sets AS set_row ON set_row.set_id=order_row.set_id
JOIN catalog_set_groups AS group_row USING(set_group_id)
WHERE order_row.previous_max_rank > order_row.child_rank;

CREATE VIEW candidate_software_data_area_numbers AS
SELECT area.area_id,
       (
WITH RECURSIVE
source(value) AS (VALUES ((area.declared_size_text))),
token AS (
    SELECT value,
           CASE WHEN substr(value, 1, 2) IN ('0x', '0X') THEN 16 WHEN length(value) > 1 AND substr(value, 1, 1) = '0' THEN 8 ELSE 10 END AS radix,
           CASE WHEN substr(value, 1, 2) IN ('0x', '0X') THEN substr(value, 3) ELSE value END AS raw_digits
    FROM source
    WHERE typeof(value) = 'text'
      AND instr(CAST(value AS BLOB), X'00') = 0
      AND instr(value, '+') = 0
),
prepared AS (
    SELECT radix, ltrim(raw_digits, '0') AS significant
    FROM token
    WHERE raw_digits <> ''
      AND raw_digits NOT GLOB
          (CASE radix WHEN 16 THEN '*[^0-9a-fA-F]*'
                      WHEN 8 THEN '*[^0-7]*'
                      ELSE '*[^0-9]*' END)
),
bounded AS (
    SELECT radix, coalesce(nullif(significant, ''), '0') AS digits
    FROM prepared
    WHERE (radix = 10 AND
           (length(significant) < 19 OR
            (length(significant) = 19 AND significant COLLATE BINARY <= '9223372036854775807')))
       OR (radix = 8 AND length(significant) <= 21)
       OR (radix = 16 AND length(significant) <= 16)
),
fold(position, radix, digits, accumulator, valid) AS (
    SELECT 1, radix, digits, 0, 1
    FROM bounded
    WHERE radix IN (8, 16)
    UNION ALL
    SELECT position + 1,
           radix,
           digits,
           CASE WHEN valid = 1 AND (instr('0123456789abcdef', lower(substr(digits, position, 1))) - 1) >= 0 AND (instr('0123456789abcdef', lower(substr(digits, position, 1))) - 1) < radix AND accumulator <= (9223372036854775807 - (instr('0123456789abcdef', lower(substr(digits, position, 1))) - 1)) / radix
                THEN accumulator * radix + (instr('0123456789abcdef', lower(substr(digits, position, 1))) - 1)
                ELSE accumulator END,
           CASE WHEN valid = 1 AND (instr('0123456789abcdef', lower(substr(digits, position, 1))) - 1) >= 0 AND (instr('0123456789abcdef', lower(substr(digits, position, 1))) - 1) < radix AND accumulator <= (9223372036854775807 - (instr('0123456789abcdef', lower(substr(digits, position, 1))) - 1)) / radix THEN 1 ELSE 0 END
    FROM fold
    WHERE position <= length(digits)
),
fold_result AS (
    SELECT accumulator, valid
    FROM fold
    WHERE position = length(digits) + 1
)
SELECT CASE
    WHEN EXISTS (SELECT 1 FROM bounded WHERE radix = 10)
        THEN (SELECT CAST(digits AS INTEGER) FROM bounded WHERE radix = 10)
    WHEN EXISTS (SELECT 1 FROM fold_result WHERE valid = 1)
        THEN (SELECT accumulator FROM fold_result WHERE valid = 1)
    ELSE NULL
END
) AS byte_length
FROM software_data_areas AS area;

