           CASE WHEN valid = 1 AND (instr('0123456789abcdef', lower(substr(digits, position, 1))) - 1) >= 0 AND (instr('0123456789abcdef', lower(substr(digits, position, 1))) - 1) < radix AND accumulator <= (9223372036854775807 - (instr('0123456789abcdef', lower(substr(digits, position, 1))) - 1)) / radix
                THEN accumulator * radix + (instr('0123456789abcdef', lower(substr(digits, position, 1))) - 1)
                ELSE accumulator END,
           CASE WHEN valid = 1 AND (instr('0123456789abcdef', lower(substr(digits, position, 1))) - 1) >= 0 AND (instr('0123456789abcdef', lower(substr(digits, position, 1))) - 1) < radix AND accumulator <= (9223372036854775807 - (instr('0123456789abcdef', lower(substr(digits, position, 1))) - 1)) / radix THEN 1 ELSE 0 END
    FROM fold
