) AS byte_offset
FROM software_rom_load_entries AS rom;
CREATE INDEX IF NOT EXISTS candidate_software_file_steps_by_required_file
    ON software_file_load_steps(required_file_id, load_entry_id);

CREATE VIEW candidate_software_file_lengths AS
SELECT root.media_entry_id,
       (
           WITH RECURSIVE walk(
               root_media_entry_id, data_area_id, edition_id, required_file_id,
               source_order, byte_length, state
           ) AS (
               SELECT root.media_entry_id, root.data_area_id, groups.edition_id,
                      requirement.required_file_id, root.source_order,
                      root_numbers.byte_length, 'walking'
               FROM catalog_media_entries AS media
               JOIN catalog_source_elements AS element
                 ON element.source_element_id = media.media_entry_id
                AND element.element_kind = 'software_rom_entry'
               JOIN software_areas AS area
                 ON area.area_id = root.data_area_id AND area.kind = 'data'
               JOIN software_data_areas AS data ON data.area_id = area.area_id
               JOIN software_parts AS part ON part.part_id = area.part_id
               JOIN software_titles AS title ON title.set_id = part.set_id
               JOIN catalog_sets AS sets ON sets.set_id = title.set_id
               JOIN catalog_set_groups AS groups ON groups.set_group_id = sets.set_group_id
               JOIN software_lists AS lists ON lists.set_group_id = groups.set_group_id
               JOIN software_required_files AS requirement
                 ON requirement.first_load_entry_id = root.media_entry_id
               JOIN software_file_load_steps AS root_step
                 ON root_step.load_entry_id = root.media_entry_id
                AND root_step.required_file_id = requirement.required_file_id
               JOIN candidate_software_rom_numbers AS root_numbers
                 ON root_numbers.media_entry_id = root.media_entry_id
               WHERE media.media_entry_id = root.media_entry_id
                 AND groups.group_kind = 'software_list'
                 AND element.edition_id = groups.edition_id
                 AND root_numbers.byte_length > 0
                 AND NOT EXISTS (
                     SELECT 1
                     FROM software_file_load_steps AS elsewhere_step
                     JOIN software_rom_load_entries AS elsewhere
                       ON elsewhere.media_entry_id = elsewhere_step.load_entry_id
                     WHERE elsewhere_step.required_file_id = requirement.required_file_id
                       AND elsewhere.data_area_id <> root.data_area_id
                 )

               UNION ALL

               SELECT walk.root_media_entry_id, walk.data_area_id, walk.edition_id,
                      walk.required_file_id, next_rom.source_order,
                      CASE
                          WHEN next_rom.source_order = walk.source_order + 1
                           AND next_operation.operation IN ('continue', 'ignore')
                           AND (
        (
        next_media.media_entry_id IS NOT NULL
        AND next_element.element_kind = 'software_rom_entry'
        AND next_step.load_entry_id IS NOT NULL
    )
        AND next_step.required_file_id = walk.required_file_id
        AND next_requirement.required_file_id IS NULL
        AND linked_requirement.first_load_entry_id = walk.root_media_entry_id
    )
                           AND (
        CASE next_operation.operation WHEN 'continue'
             THEN next_numbers.byte_length > 0
             WHEN 'ignore' THEN next_numbers.byte_length >= 0
             ELSE 0 END
    )
                           AND next_numbers.byte_length <= 9223372036854775807 - walk.byte_length
                          THEN walk.byte_length + next_numbers.byte_length
                          ELSE walk.byte_length
                      END,
                      CASE
                          WHEN next_rom.source_order <> walk.source_order + 1
                          THEN 'invalid'
                          WHEN next_operation.operation IN ('continue', 'ignore') THEN
                              CASE WHEN (
        (
        next_media.media_entry_id IS NOT NULL
        AND next_element.element_kind = 'software_rom_entry'
        AND next_step.load_entry_id IS NOT NULL
    )
        AND next_step.required_file_id = walk.required_file_id
        AND next_requirement.required_file_id IS NULL
        AND linked_requirement.first_load_entry_id = walk.root_media_entry_id
    )
                                         AND (
        CASE next_operation.operation WHEN 'continue'
             THEN next_numbers.byte_length > 0
             WHEN 'ignore' THEN next_numbers.byte_length >= 0
             ELSE 0 END
    )
                                         AND next_numbers.byte_length <= 9223372036854775807 - walk.byte_length
                                   THEN 'walking' ELSE 'invalid' END
                          WHEN next_operation.operation IN ('reload', 'reload_plain') THEN
                              CASE WHEN (
        next_media.media_entry_id IS NOT NULL
        AND next_element.element_kind = 'software_rom_entry'
        AND next_step.load_entry_id IS NOT NULL
    )
                                         AND next_step.required_file_id = walk.required_file_id
                                         AND next_requirement.required_file_id IS NULL
                                         AND linked_requirement.first_load_entry_id = walk.root_media_entry_id
                                   THEN 'complete' ELSE 'invalid' END
                          WHEN next_operation.operation = 'load' THEN
                              CASE WHEN (
        next_media.media_entry_id IS NOT NULL
        AND next_element.element_kind = 'software_rom_entry'
        AND next_step.load_entry_id IS NOT NULL
    )
                                         AND next_step.required_file_id = next_requirement.required_file_id
                                         AND next_requirement.first_load_entry_id = next_rom.media_entry_id
                                   THEN 'complete' ELSE 'invalid' END
                          WHEN next_operation.operation = 'fill' THEN
                              CASE WHEN (
        next_media.media_entry_id IS NOT NULL
        AND next_element.element_kind = 'software_rom_entry'
        AND next_step.load_entry_id IS NOT NULL
    )
                                         AND next_step.required_file_id IS NULL
                                         AND next_requirement.required_file_id IS NULL
                                   THEN 'complete' ELSE 'invalid' END
                          ELSE 'invalid'
                      END
               FROM walk
               JOIN software_rom_load_entries AS next_rom
                 ON next_rom.data_area_id = walk.data_area_id
               AND next_rom.source_order = (
                    SELECT min(later.source_order)
                    FROM software_rom_load_entries AS later
                    WHERE later.data_area_id = walk.data_area_id
                      AND later.source_order > walk.source_order
                )
               JOIN candidate_software_rom_operations AS next_operation
                 ON next_operation.media_entry_id = next_rom.media_entry_id
               JOIN candidate_software_rom_numbers AS next_numbers
                 ON next_numbers.media_entry_id = next_rom.media_entry_id
               LEFT JOIN catalog_media_entries AS next_media
                 ON next_media.media_entry_id = next_rom.media_entry_id
               LEFT JOIN catalog_source_elements AS next_element
                 ON next_element.source_element_id = next_media.media_entry_id
               LEFT JOIN software_file_load_steps AS next_step
                 ON next_step.load_entry_id = next_rom.media_entry_id
               LEFT JOIN software_required_files AS next_requirement
                 ON next_requirement.first_load_entry_id = next_rom.media_entry_id
               LEFT JOIN software_required_files AS linked_requirement
                 ON linked_requirement.required_file_id = next_step.required_file_id
               WHERE walk.state = 'walking'
                 AND (next_element.edition_id IS NULL OR next_element.edition_id = walk.edition_id)
           )
           SELECT CASE
                      WHEN walk.state = 'complete' THEN walk.byte_length
                      WHEN walk.state = 'walking'
                       AND NOT EXISTS (
                           SELECT 1 FROM software_rom_load_entries AS later
                           WHERE later.data_area_id = walk.data_area_id
                             AND later.source_order > walk.source_order
                       ) THEN walk.byte_length
                      ELSE NULL
                  END
           FROM walk
           ORDER BY walk.source_order DESC
           LIMIT 1
       ) AS byte_length
FROM software_rom_load_entries AS root
JOIN candidate_software_rom_operations AS root_operation
  ON root_operation.media_entry_id = root.media_entry_id
WHERE root_operation.operation = 'load';
CREATE VIEW candidate_native_file_sizes AS
SELECT media.media_entry_id,
       CASE source.element_kind
           WHEN 'software_rom_entry' THEN 'file_length'
           ELSE 'size'
       END AS source_size_field,
       CASE
           WHEN source.element_kind = 'mame_rom' THEN (SELECT CASE
    WHEN typeof((mame_roms.size_text)) = 'text'
     AND instr(CAST((mame_roms.size_text) AS BLOB), X'00') = 0
     AND length((mame_roms.size_text)) > 0
     AND (mame_roms.size_text) NOT GLOB '*[^0-9]*'
     AND (length(ltrim((mame_roms.size_text), '0')) < 19 OR
          (length(ltrim((mame_roms.size_text), '0')) = 19 AND ltrim((mame_roms.size_text), '0') COLLATE BINARY <= '9223372036854775807'))
    THEN CAST(CASE WHEN ltrim((mame_roms.size_text), '0') = '' THEN '0' ELSE ltrim((mame_roms.size_text), '0') END AS INTEGER)
END FROM mame_roms WHERE media_entry_id = media.media_entry_id)
           WHEN source.element_kind = 'software_rom_entry' THEN (SELECT length.byte_length FROM candidate_software_file_lengths AS length WHERE length.media_entry_id = media.media_entry_id)
           WHEN source.element_kind = 'clrmamepro_rom' THEN (SELECT clrmamepro_roms.size_value FROM clrmamepro_roms WHERE media_entry_id = media.media_entry_id)
           WHEN source.element_kind = 'logiqx_rom' THEN (SELECT logiqx_roms.size_value FROM logiqx_roms WHERE media_entry_id = media.media_entry_id)
           WHEN source.element_kind = 'no_intro_dat_rom' THEN
               (SELECT CASE WHEN rules.dialect IN ('no-intro-dat-v3-strict', 'no-intro-dat-v4-strict') THEN ((
WITH
source(raw) AS NOT MATERIALIZED (VALUES ((rom.size_text))),
trimmed(value) AS (
    SELECT trim(raw, char(9) || char(10) || char(13) || ' ')
    FROM source
    WHERE typeof(raw) = 'text'
      AND instr(CAST(raw AS BLOB), X'00') = 0
),
signed(value, negative, digits) AS (
    SELECT value,
           substr(value, 1, 1) = '-',
           CASE WHEN substr(value, 1, 1) IN ('+', '-')
                THEN substr(value, 2) ELSE value END
    FROM trimmed
),
parsed(negative, significant) AS (
    SELECT negative, coalesce(nullif(ltrim(digits, '0'), ''), '0')
    FROM signed
    WHERE digits <> '' AND digits NOT GLOB '*[^0-9]*'
),
accepted(negative, significant) AS (
    SELECT negative, significant
    FROM parsed
    WHERE CASE
        WHEN significant = '0' THEN 1
        WHEN negative THEN (0) AND (1)
        ELSE (1) AND ((length(significant) < length('4294967295') OR (length(significant) = length('4294967295') AND significant COLLATE BINARY <= '4294967295')))
    END
)
SELECT CASE
    WHEN significant = '0' THEN 0
    WHEN negative THEN CASE WHEN significant = '9223372036854775808' THEN (-9223372036854775807 - 1) ELSE -CAST(significant AS INTEGER) END
    ELSE CAST(significant AS INTEGER)
END
FROM accepted
)) WHEN rules.dialect IN ('no-intro-dat-v3-compatible', 'no-intro-dat-v4-compatible') THEN (CASE
    WHEN typeof((rom.size_text)) = 'text'
     AND instr(CAST((rom.size_text) AS BLOB), X'00') = 0
     AND length((rom.size_text)) > 0
     AND (rom.size_text) NOT GLOB '*[^0-9]*'
     AND (length(ltrim((rom.size_text), '0')) < 19 OR
          (length(ltrim((rom.size_text), '0')) = 19 AND ltrim((rom.size_text), '0') COLLATE BINARY <= '9223372036854775807'))
    THEN CAST(CASE WHEN ltrim((rom.size_text), '0') = '' THEN '0' ELSE ltrim((rom.size_text), '0') END AS INTEGER)
END) END FROM no_intro_dat_rom_claims AS rom
                WHERE rom.media_entry_id = media.media_entry_id)
           WHEN source.element_kind = 'no_intro_pc_rom' THEN (SELECT no_intro_pc_file_claims.size_i64 FROM no_intro_pc_file_claims WHERE media_entry_id = media.media_entry_id)
           WHEN source.element_kind = 'no_intro_export_source_file' THEN (SELECT CASE
    WHEN typeof((no_intro_dump_files.size_text)) = 'text'
     AND instr(CAST((no_intro_dump_files.size_text) AS BLOB), X'00') = 0
     AND length((no_intro_dump_files.size_text)) > 0
     AND (no_intro_dump_files.size_text) NOT GLOB '*[^0-9]*'
     AND (length(ltrim((no_intro_dump_files.size_text), '0')) < 19 OR
          (length(ltrim((no_intro_dump_files.size_text), '0')) = 19 AND ltrim((no_intro_dump_files.size_text), '0') COLLATE BINARY <= '9223372036854775807'))
    THEN CAST(CASE WHEN ltrim((no_intro_dump_files.size_text), '0') = '' THEN '0' ELSE ltrim((no_intro_dump_files.size_text), '0') END AS INTEGER)
END FROM no_intro_dump_files WHERE media_entry_id = media.media_entry_id)
           WHEN source.element_kind = 'no_intro_export_release_file' THEN (SELECT CASE
    WHEN typeof((no_intro_release_files.size_text)) = 'text'
     AND instr(CAST((no_intro_release_files.size_text) AS BLOB), X'00') = 0
     AND length((no_intro_release_files.size_text)) > 0
     AND (no_intro_release_files.size_text) NOT GLOB '*[^0-9]*'
     AND (length(ltrim((no_intro_release_files.size_text), '0')) < 19 OR
          (length(ltrim((no_intro_release_files.size_text), '0')) = 19 AND ltrim((no_intro_release_files.size_text), '0') COLLATE BINARY <= '9223372036854775807'))
    THEN CAST(CASE WHEN ltrim((no_intro_release_files.size_text), '0') = '' THEN '0' ELSE ltrim((no_intro_release_files.size_text), '0') END AS INTEGER)
END FROM no_intro_release_files WHERE media_entry_id = media.media_entry_id)
       END AS byte_length,
       CASE
           WHEN source.element_kind = 'mame_rom' THEN coalesce(((SELECT CASE WHEN mame_roms.size_text IS NULL THEN 'omitted'
                 WHEN (CASE
    WHEN typeof((mame_roms.size_text)) = 'text'
     AND instr(CAST((mame_roms.size_text) AS BLOB), X'00') = 0
     AND length((mame_roms.size_text)) > 0
     AND (mame_roms.size_text) NOT GLOB '*[^0-9]*'
     AND (length(ltrim((mame_roms.size_text), '0')) < 19 OR
          (length(ltrim((mame_roms.size_text), '0')) = 19 AND ltrim((mame_roms.size_text), '0') COLLATE BINARY <= '9223372036854775807'))
    THEN CAST(CASE WHEN ltrim((mame_roms.size_text), '0') = '' THEN '0' ELSE ltrim((mame_roms.size_text), '0') END AS INTEGER)
END) IS NULL THEN 'unusable'
                 ELSE 'value' END
          FROM mame_roms
         WHERE mame_roms.media_entry_id = media.media_entry_id)), 'unusable') WHEN source.element_kind = 'software_rom_entry' THEN CASE WHEN ((SELECT length.byte_length FROM candidate_software_file_lengths AS length WHERE length.media_entry_id = media.media_entry_id)) IS NULL THEN 'unusable' ELSE 'value' END WHEN source.element_kind = 'clrmamepro_rom' THEN coalesce(((SELECT CASE WHEN clrmamepro_roms.size_text IS NULL THEN 'omitted'
                 WHEN (clrmamepro_roms.size_value) IS NULL THEN 'unusable'
                 ELSE 'value' END
          FROM clrmamepro_roms
         WHERE clrmamepro_roms.media_entry_id = media.media_entry_id)), 'unusable') WHEN source.element_kind = 'logiqx_rom' THEN coalesce(((SELECT CASE WHEN logiqx_roms.size_text IS NULL THEN 'omitted'
                 WHEN (logiqx_roms.size_value) IS NULL THEN 'unusable'
                 ELSE 'value' END
          FROM logiqx_roms
         WHERE logiqx_roms.media_entry_id = media.media_entry_id)), 'unusable') WHEN source.element_kind = 'no_intro_dat_rom' THEN coalesce((SELECT CASE WHEN rom.size_text IS NULL THEN 'omitted' WHEN (CASE WHEN rules.dialect IN ('no-intro-dat-v3-strict', 'no-intro-dat-v4-strict') THEN ((
WITH
source(raw) AS NOT MATERIALIZED (VALUES ((rom.size_text))),
trimmed(value) AS (
    SELECT trim(raw, char(9) || char(10) || char(13) || ' ')
    FROM source
    WHERE typeof(raw) = 'text'
      AND instr(CAST(raw AS BLOB), X'00') = 0
),
signed(value, negative, digits) AS (
    SELECT value,
           substr(value, 1, 1) = '-',
           CASE WHEN substr(value, 1, 1) IN ('+', '-')
                THEN substr(value, 2) ELSE value END
    FROM trimmed
),
parsed(negative, significant) AS (
    SELECT negative, coalesce(nullif(ltrim(digits, '0'), ''), '0')
    FROM signed
    WHERE digits <> '' AND digits NOT GLOB '*[^0-9]*'
),
accepted(negative, significant) AS (
    SELECT negative, significant
    FROM parsed
    WHERE CASE
        WHEN significant = '0' THEN 1
        WHEN negative THEN (0) AND (1)
        ELSE (1) AND ((length(significant) < length('4294967295') OR (length(significant) = length('4294967295') AND significant COLLATE BINARY <= '4294967295')))
    END
)
SELECT CASE
    WHEN significant = '0' THEN 0
    WHEN negative THEN CASE WHEN significant = '9223372036854775808' THEN (-9223372036854775807 - 1) ELSE -CAST(significant AS INTEGER) END
    ELSE CAST(significant AS INTEGER)
END
FROM accepted
)) WHEN rules.dialect IN ('no-intro-dat-v3-compatible', 'no-intro-dat-v4-compatible') THEN (CASE
    WHEN typeof((rom.size_text)) = 'text'
     AND instr(CAST((rom.size_text) AS BLOB), X'00') = 0
     AND length((rom.size_text)) > 0
     AND (rom.size_text) NOT GLOB '*[^0-9]*'
     AND (length(ltrim((rom.size_text), '0')) < 19 OR
          (length(ltrim((rom.size_text), '0')) = 19 AND ltrim((rom.size_text), '0') COLLATE BINARY <= '9223372036854775807'))
    THEN CAST(CASE WHEN ltrim((rom.size_text), '0') = '' THEN '0' ELSE ltrim((rom.size_text), '0') END AS INTEGER)
END) END) IS NULL THEN 'unusable' ELSE 'value' END FROM no_intro_dat_rom_claims AS rom WHERE rom.media_entry_id = media.media_entry_id), 'unusable') WHEN source.element_kind = 'no_intro_pc_rom' THEN coalesce(((SELECT CASE WHEN no_intro_pc_file_claims.size_text IS NULL THEN 'omitted'
                 WHEN (no_intro_pc_file_claims.size_i64) IS NULL THEN 'unusable'
                 ELSE 'value' END
          FROM no_intro_pc_file_claims
         WHERE no_intro_pc_file_claims.media_entry_id = media.media_entry_id)), 'unusable') WHEN source.element_kind = 'no_intro_export_source_file' THEN coalesce(((SELECT CASE WHEN no_intro_dump_files.size_text IS NULL THEN 'omitted'
                 WHEN (CASE
    WHEN typeof((no_intro_dump_files.size_text)) = 'text'
     AND instr(CAST((no_intro_dump_files.size_text) AS BLOB), X'00') = 0
     AND length((no_intro_dump_files.size_text)) > 0
     AND (no_intro_dump_files.size_text) NOT GLOB '*[^0-9]*'
     AND (length(ltrim((no_intro_dump_files.size_text), '0')) < 19 OR
          (length(ltrim((no_intro_dump_files.size_text), '0')) = 19 AND ltrim((no_intro_dump_files.size_text), '0') COLLATE BINARY <= '9223372036854775807'))
    THEN CAST(CASE WHEN ltrim((no_intro_dump_files.size_text), '0') = '' THEN '0' ELSE ltrim((no_intro_dump_files.size_text), '0') END AS INTEGER)
END) IS NULL THEN 'unusable'
                 ELSE 'value' END
          FROM no_intro_dump_files
         WHERE no_intro_dump_files.media_entry_id = media.media_entry_id)), 'unusable') WHEN source.element_kind = 'no_intro_export_release_file' THEN coalesce(((SELECT CASE WHEN no_intro_release_files.size_text IS NULL THEN 'omitted'
                 WHEN (CASE
    WHEN typeof((no_intro_release_files.size_text)) = 'text'
     AND instr(CAST((no_intro_release_files.size_text) AS BLOB), X'00') = 0
     AND length((no_intro_release_files.size_text)) > 0
     AND (no_intro_release_files.size_text) NOT GLOB '*[^0-9]*'
     AND (length(ltrim((no_intro_release_files.size_text), '0')) < 19 OR
          (length(ltrim((no_intro_release_files.size_text), '0')) = 19 AND ltrim((no_intro_release_files.size_text), '0') COLLATE BINARY <= '9223372036854775807'))
    THEN CAST(CASE WHEN ltrim((no_intro_release_files.size_text), '0') = '' THEN '0' ELSE ltrim((no_intro_release_files.size_text), '0') END AS INTEGER)
END) IS NULL THEN 'unusable'
                 ELSE 'value' END
          FROM no_intro_release_files
         WHERE no_intro_release_files.media_entry_id = media.media_entry_id)), 'unusable')
       END AS size_state
FROM catalog_media_entries AS media
CROSS JOIN catalog_source_elements AS source
  ON source.source_element_id = media.media_entry_id
CROSS JOIN catalog_editions AS edition
  ON edition.edition_id = source.edition_id
CROSS JOIN catalog_reading_rules AS rules
  ON rules.reading_rules_id = edition.reading_rules_id
WHERE source.element_kind IN (
    'mame_rom', 'software_rom_entry', 'clrmamepro_rom', 'logiqx_rom',
    'no_intro_dat_rom', 'no_intro_pc_rom',
    'no_intro_export_source_file', 'no_intro_export_release_file'
)
  AND (source.element_kind <> 'software_rom_entry' OR EXISTS (
       SELECT 1 FROM candidate_software_file_lengths AS software
       WHERE software.media_entry_id = media.media_entry_id
  ))
  AND (source.element_kind <> 'no_intro_dat_rom' OR
       (rules.format_family = 'no_intro_dat' AND rules.dialect IN (
           'no-intro-dat-v3-strict', 'no-intro-dat-v4-strict',
           'no-intro-dat-v3-compatible', 'no-intro-dat-v4-compatible'
       )));
CREATE VIEW candidate_native_file_roles AS
SELECT media.media_entry_id, element.edition_id, rules.format_family,
       CASE element.element_kind
           WHEN 'mame_rom' THEN 'mame_0289_machine_rom'
           WHEN 'software_rom_entry' THEN 'mame_0289_software_file'
           WHEN 'logiqx_rom' THEN 'logiqx_complete_declared_file'
           WHEN 'clrmamepro_rom' THEN 'clrmamepro_declared_asset'
           WHEN 'no_intro_dat_rom' THEN 'no_intro_dat_unfiltered_file'
           WHEN 'no_intro_pc_rom' THEN 'no_intro_pc_fixture_asset'
       END AS contract_kind,
       CASE element.element_kind WHEN 'software_rom_entry' THEN 'file_length'
            ELSE 'size' END AS source_size_field
FROM catalog_media_entries AS media
CROSS JOIN catalog_source_elements AS element ON element.source_element_id=media.media_entry_id
CROSS JOIN catalog_editions AS edition ON edition.edition_id=element.edition_id
CROSS JOIN catalog_reading_rules AS rules ON rules.reading_rules_id=edition.reading_rules_id
WHERE CASE element.element_kind
WHEN 'mame_rom' THEN rules.format_family='mame' AND EXISTS (
    SELECT 1 FROM mame_roms AS rom
    JOIN mame_machines AS machine ON machine.set_id=rom.machine_id
    JOIN catalog_sets AS sets ON sets.set_id=machine.set_id
    JOIN catalog_set_groups AS groups ON groups.set_group_id=sets.set_group_id
    WHERE rom.media_entry_id=media.media_entry_id AND groups.edition_id=element.edition_id
      AND rom.status<>'nodump' AND length(rom.name)>0
      AND NOT EXISTS (
          SELECT 1 FROM mame_rom_compatibility AS compatibility
          WHERE compatibility.media_entry_id=rom.media_entry_id
            AND (compatibility.loadflag IS NOT NULL OR compatibility.value IS NOT NULL
              OR compatibility.inverted IS NOT NULL OR compatibility.ovha IS NOT NULL
              OR compatibility.nothread IS NOT NULL OR compatibility.soundonly IS NOT NULL
              OR compatibility.dispose IS NOT NULL)
      )
)
WHEN 'software_rom_entry' THEN rules.format_family='software' AND EXISTS (
    SELECT 1 FROM software_rom_load_entries AS rom
    JOIN candidate_software_rom_operations AS operation
      ON operation.media_entry_id=rom.media_entry_id AND operation.operation='load'
    JOIN candidate_software_file_lengths AS length
      ON length.media_entry_id=rom.media_entry_id AND length.byte_length>0
    JOIN software_required_files AS required ON required.first_load_entry_id=rom.media_entry_id
    JOIN software_areas AS area ON area.area_id=rom.data_area_id AND area.kind='data'
    JOIN software_parts AS part ON part.part_id=area.part_id
    JOIN software_titles AS title ON title.set_id=part.set_id
    JOIN catalog_sets AS sets ON sets.set_id=title.set_id
    JOIN catalog_set_groups AS groups ON groups.set_group_id=sets.set_group_id
    WHERE rom.media_entry_id=media.media_entry_id AND groups.edition_id=element.edition_id
      AND rom.status<>'nodump' AND rom.name IS NOT NULL AND length(rom.name)>0
)
WHEN 'logiqx_rom' THEN rules.format_family='logiqx' AND EXISTS (
    SELECT 1 FROM logiqx_roms AS rom
    JOIN logiqx_games AS game ON game.set_id=rom.set_id
    JOIN catalog_sets AS sets ON sets.set_id=game.set_id
    JOIN catalog_set_groups AS groups ON groups.set_group_id=sets.set_group_id
    WHERE rom.media_entry_id=media.media_entry_id AND groups.edition_id=element.edition_id
      AND rom.status<>'nodump' AND length(rom.name)>0
)
WHEN 'clrmamepro_rom' THEN rules.format_family='clrmamepro' AND EXISTS (
    SELECT 1 FROM clrmamepro_roms AS rom
    JOIN clrmamepro_sets AS game ON game.set_id=rom.set_id
    JOIN catalog_sets AS sets ON sets.set_id=game.set_id
    JOIN catalog_set_groups AS groups ON groups.set_group_id=sets.set_group_id
    JOIN clrmamepro_rom_details AS details ON details.media_entry_id=rom.media_entry_id
    WHERE rom.media_entry_id=media.media_entry_id AND groups.edition_id=element.edition_id
      AND length(rom.name)>0
)
WHEN 'no_intro_dat_rom' THEN rules.format_family='no_intro_dat' AND EXISTS (
    SELECT 1 FROM no_intro_dat_rom_claims AS rom
    JOIN no_intro_dat_games AS game ON game.set_id=rom.set_id
    JOIN catalog_sets AS sets ON sets.set_id=game.set_id
    JOIN catalog_set_groups AS groups ON groups.set_group_id=sets.set_group_id
    WHERE rom.media_entry_id=media.media_entry_id AND groups.edition_id=element.edition_id
      AND length(rom.name)>0 AND coalesce(rom.status_text,'')<>'nodump'
      AND rom.header_text IS NULL
      AND NOT EXISTS (
          SELECT 1 FROM no_intro_dat_headers AS header
          JOIN no_intro_dat_clrmamepro_options AS filter USING(header_id)
          WHERE header.set_group_id=groups.set_group_id AND filter.header IS NOT NULL
      )
      AND NOT EXISTS (
          SELECT 1 FROM no_intro_dat_rom_field_positions AS position
          WHERE position.media_entry_id=rom.media_entry_id AND position.field_kind='header'
      )
)
WHEN 'no_intro_pc_rom' THEN rules.format_family='no_intro_pc_fixture' AND EXISTS (
    SELECT 1 FROM no_intro_pc_file_claims AS rom
    JOIN no_intro_pc_games AS game ON game.set_id=rom.set_id
    JOIN catalog_sets AS sets ON sets.set_id=game.set_id
    JOIN catalog_set_groups AS groups ON groups.set_group_id=sets.set_group_id
    WHERE rom.media_entry_id=media.media_entry_id AND groups.edition_id=element.edition_id
      AND length(rom.name)>0
)
ELSE 0 END;

CREATE VIEW candidate_native_file_byte_coverage AS
SELECT role.media_entry_id, role.edition_id, role.format_family,
       role.contract_kind, role.source_size_field, size.size_state,
       size.byte_length
FROM candidate_native_file_roles AS role
JOIN catalog_editions AS edition ON edition.edition_id = role.edition_id
JOIN catalog_file_byte_contracts AS contract
  ON contract.reading_rules_id = edition.reading_rules_id
 AND contract.contract_kind = role.contract_kind
JOIN candidate_native_file_sizes AS size
  ON size.media_entry_id = role.media_entry_id
 AND size.source_size_field = role.source_size_field;

CREATE VIEW candidate_native_file_qualification AS
SELECT coverage.media_entry_id
FROM candidate_native_file_byte_coverage AS coverage
WHERE ((coverage.size_state = 'omitted' AND coverage.byte_length IS NULL)
    OR (coverage.size_state = 'value'
        AND typeof(coverage.byte_length) = 'integer' AND coverage.byte_length >= 0
        AND (coverage.contract_kind <> 'mame_0289_software_file' OR coverage.byte_length > 0)))
  AND NOT EXISTS (
      SELECT 1 FROM catalog_entry_hashes AS bad
      WHERE bad.media_entry_id = coverage.media_entry_id
        AND (bad.presence <> 'value'
          OR bad.source_hash_field NOT IN ('crc', 'crc32', 'md5', 'sha1', 'sha256')
          OR bad.hash_scope NOT IN ('whole_file', 'whole_asset')
          OR NOT EXISTS (
              SELECT 1 FROM candidate_canonical_hash_positions AS position
              WHERE position.reported_hash_id = bad.reported_hash_id
                AND position.media_entry_id = coverage.media_entry_id
                AND position.source_hash_field = bad.source_hash_field
                AND position.field_occurrence = bad.field_occurrence
          )
          OR NOT EXISTS (
              SELECT 1 FROM hash_values AS value
              WHERE value.hash_id = bad.hash_id
                AND value.algorithm = CASE bad.source_hash_field
                    WHEN 'crc' THEN 'crc32' WHEN 'crc32' THEN 'crc32'
                    WHEN 'md5' THEN 'md5' WHEN 'sha1' THEN 'sha1'
                    WHEN 'sha256' THEN 'sha256' END
                AND length(value.bytes) = CASE value.algorithm
                    WHEN 'crc32' THEN 4 WHEN 'md5' THEN 16
                    WHEN 'sha1' THEN 20 WHEN 'sha256' THEN 32 END
          ))
  )
  AND NOT EXISTS (
      SELECT 1
      FROM catalog_entry_hashes AS left_hash
      JOIN hash_values AS left_value ON left_value.hash_id = left_hash.hash_id
      JOIN catalog_entry_hashes AS right_hash
        ON right_hash.media_entry_id = left_hash.media_entry_id
       AND right_hash.reported_hash_id > left_hash.reported_hash_id
      JOIN hash_values AS right_value ON right_value.hash_id = right_hash.hash_id
       AND right_value.algorithm = left_value.algorithm
      WHERE left_hash.media_entry_id = coverage.media_entry_id
        AND left_hash.presence = 'value' AND right_hash.presence = 'value'
        AND left_hash.hash_id <> right_hash.hash_id
  );

CREATE VIEW candidate_qualified_file_hashes AS
SELECT declaration.reported_hash_id, declaration.media_entry_id,
       declaration.hash_id, declaration.hash_scope,
       declaration.source_hash_field
FROM catalog_entry_hashes AS declaration
CROSS JOIN hash_values AS value ON value.hash_id = declaration.hash_id
WHERE declaration.presence = 'value'
  AND declaration.source_hash_field IN ('crc', 'crc32', 'md5', 'sha1', 'sha256')
  AND declaration.hash_scope IN ('whole_file', 'whole_asset')
  AND value.algorithm = CASE declaration.source_hash_field
      WHEN 'crc' THEN 'crc32' WHEN 'crc32' THEN 'crc32'
      WHEN 'md5' THEN 'md5' WHEN 'sha1' THEN 'sha1'
      WHEN 'sha256' THEN 'sha256' END
  AND length(value.bytes) = CASE value.algorithm
      WHEN 'crc32' THEN 4 WHEN 'md5' THEN 16
      WHEN 'sha1' THEN 20 WHEN 'sha256' THEN 32 END
  AND EXISTS (
      SELECT 1 FROM candidate_native_file_byte_coverage AS coverage
      WHERE coverage.media_entry_id = declaration.media_entry_id
  )
  AND EXISTS (
      SELECT 1 FROM candidate_canonical_hash_positions AS position
      WHERE position.reported_hash_id = declaration.reported_hash_id
        AND position.media_entry_id = declaration.media_entry_id
        AND position.source_hash_field = declaration.source_hash_field
        AND position.field_occurrence = declaration.field_occurrence
  );

CREATE VIEW candidate_file_qualification_problems AS
SELECT 'linked_media_not_eligible_native_file' AS problem,
       media.media_entry_id AS owner_id, element.edition_id
FROM catalog_media_entries AS media
JOIN catalog_source_elements AS element
  ON element.source_element_id = media.media_entry_id
WHERE media.file_uuid IS NOT NULL
  AND NOT EXISTS (
      SELECT 1 FROM candidate_native_file_qualification AS qualification
      WHERE qualification.media_entry_id = media.media_entry_id
  )
UNION ALL
SELECT 'linked_media_without_qualified_strong_hash',
       media.media_entry_id, element.edition_id
FROM catalog_media_entries AS media
JOIN catalog_source_elements AS element
  ON element.source_element_id = media.media_entry_id
WHERE media.file_uuid IS NOT NULL
  AND EXISTS (
      SELECT 1 FROM candidate_native_file_qualification AS qualification
      WHERE qualification.media_entry_id = media.media_entry_id
  )
  AND NOT EXISTS (
      SELECT 1 FROM candidate_qualified_file_hashes AS hash
      JOIN hash_values AS value ON value.hash_id = hash.hash_id
      WHERE hash.media_entry_id = media.media_entry_id
        AND value.algorithm IN ('sha1', 'sha256')
  );
-- Reviews freeze already-published source facts, not provisional import
-- batches. Ordinary same-import matching still sees completed-batch facts.
CREATE TRIGGER shared_file_facts_review_requires_frozen_sources
BEFORE INSERT ON file_match_decision_publications
WHEN EXISTS (
    SELECT 1 FROM (
        SELECT media.media_entry_id
        FROM (SELECT DISTINCT canonical_file_uuid FROM (SELECT canonical_file_uuid FROM candidate_review_file_components WHERE decision_id=NEW.decision_id)) AS roots
        CROSS JOIN candidate_file_component_members AS member
          ON member.canonical_file_uuid=roots.canonical_file_uuid
        JOIN catalog_media_entries AS media ON media.file_uuid=member.file_uuid
        UNION ALL
        SELECT conflict.incoming_media_entry_id
        FROM file_match_decision_conflicts AS settled
        JOIN file_match_conflicts AS conflict USING(conflict_id)
        WHERE settled.decision_id=NEW.decision_id
        UNION ALL
        SELECT declaration.media_entry_id
        FROM file_match_decision_conflicts AS settled
        JOIN file_match_conflict_hashes AS witness USING(conflict_id)
        LEFT JOIN catalog_entry_hashes AS declaration USING(reported_hash_id)
        WHERE settled.decision_id=NEW.decision_id
        UNION ALL
        SELECT witness.media_entry_id
        FROM file_match_decision_conflicts AS settled
        JOIN file_match_conflict_sizes AS witness USING(conflict_id)
        WHERE settled.decision_id=NEW.decision_id
    ) AS owner
    LEFT JOIN catalog_source_elements AS element
      ON element.source_element_id=owner.media_entry_id
    LEFT JOIN published_catalog_editions AS publication
      ON publication.edition_id=element.edition_id
    WHERE element.source_element_id IS NULL OR publication.edition_id IS NULL
)
BEGIN SELECT RAISE(ABORT,'file-match review requires published source owners'); END;

CREATE TRIGGER shared_file_facts_after_file_match_publication
AFTER INSERT ON file_match_decision_publications
BEGIN
    DELETE FROM shared_file_hashes WHERE file_uuid IN (SELECT member.file_uuid FROM candidate_file_component_members AS member WHERE member.canonical_file_uuid IN (SELECT canonical_file_uuid FROM candidate_review_file_components WHERE decision_id=NEW.decision_id));
INSERT INTO shared_file_hashes(file_uuid,hash_id) SELECT selected.canonical_file_uuid AS file_uuid,evidence.hash_id FROM (SELECT DISTINCT canonical_file_uuid FROM (SELECT canonical_file_uuid FROM candidate_review_file_components WHERE decision_id=NEW.decision_id)) AS selected CROSS JOIN candidate_file_component_members AS member ON member.canonical_file_uuid=selected.canonical_file_uuid JOIN accepted_catalog_file_hash_evidence AS evidence ON evidence.file_uuid=member.file_uuid GROUP BY selected.canonical_file_uuid,evidence.hash_id;
SELECT RAISE(ABORT,'shared file membership is not its accepted witness set') WHERE EXISTS(SELECT file_uuid,hash_id FROM shared_file_hashes WHERE file_uuid IN (SELECT member.file_uuid FROM candidate_file_component_members AS member WHERE member.canonical_file_uuid IN (SELECT canonical_file_uuid FROM candidate_review_file_components WHERE decision_id=NEW.decision_id)) EXCEPT SELECT selected.canonical_file_uuid AS file_uuid,evidence.hash_id FROM (SELECT DISTINCT canonical_file_uuid FROM (SELECT canonical_file_uuid FROM candidate_review_file_components WHERE decision_id=NEW.decision_id)) AS selected CROSS JOIN candidate_file_component_members AS member ON member.canonical_file_uuid=selected.canonical_file_uuid JOIN accepted_catalog_file_hash_evidence AS evidence ON evidence.file_uuid=member.file_uuid GROUP BY selected.canonical_file_uuid,evidence.hash_id) OR EXISTS(SELECT selected.canonical_file_uuid AS file_uuid,evidence.hash_id FROM (SELECT DISTINCT canonical_file_uuid FROM (SELECT canonical_file_uuid FROM candidate_review_file_components WHERE decision_id=NEW.decision_id)) AS selected CROSS JOIN candidate_file_component_members AS member ON member.canonical_file_uuid=selected.canonical_file_uuid JOIN accepted_catalog_file_hash_evidence AS evidence ON evidence.file_uuid=member.file_uuid GROUP BY selected.canonical_file_uuid,evidence.hash_id EXCEPT SELECT file_uuid,hash_id FROM shared_file_hashes WHERE file_uuid IN (SELECT member.file_uuid FROM candidate_file_component_members AS member WHERE member.canonical_file_uuid IN (SELECT canonical_file_uuid FROM candidate_review_file_components WHERE decision_id=NEW.decision_id)));
DELETE FROM shared_file_sizes WHERE file_uuid IN (SELECT member.file_uuid FROM candidate_file_component_members AS member WHERE member.canonical_file_uuid IN (SELECT canonical_file_uuid FROM candidate_review_file_components WHERE decision_id=NEW.decision_id));
INSERT INTO shared_file_sizes(file_uuid,byte_length) SELECT selected.canonical_file_uuid AS file_uuid,evidence.byte_length FROM (SELECT DISTINCT canonical_file_uuid FROM (SELECT canonical_file_uuid FROM candidate_review_file_components WHERE decision_id=NEW.decision_id)) AS selected CROSS JOIN candidate_file_component_members AS member ON member.canonical_file_uuid=selected.canonical_file_uuid JOIN accepted_catalog_file_size_evidence AS evidence ON evidence.file_uuid=member.file_uuid GROUP BY selected.canonical_file_uuid,evidence.byte_length;
SELECT RAISE(ABORT,'shared file membership is not its accepted witness set') WHERE EXISTS(SELECT file_uuid,byte_length FROM shared_file_sizes WHERE file_uuid IN (SELECT member.file_uuid FROM candidate_file_component_members AS member WHERE member.canonical_file_uuid IN (SELECT canonical_file_uuid FROM candidate_review_file_components WHERE decision_id=NEW.decision_id)) EXCEPT SELECT selected.canonical_file_uuid AS file_uuid,evidence.byte_length FROM (SELECT DISTINCT canonical_file_uuid FROM (SELECT canonical_file_uuid FROM candidate_review_file_components WHERE decision_id=NEW.decision_id)) AS selected CROSS JOIN candidate_file_component_members AS member ON member.canonical_file_uuid=selected.canonical_file_uuid JOIN accepted_catalog_file_size_evidence AS evidence ON evidence.file_uuid=member.file_uuid GROUP BY selected.canonical_file_uuid,evidence.byte_length) OR EXISTS(SELECT selected.canonical_file_uuid AS file_uuid,evidence.byte_length FROM (SELECT DISTINCT canonical_file_uuid FROM (SELECT canonical_file_uuid FROM candidate_review_file_components WHERE decision_id=NEW.decision_id)) AS selected CROSS JOIN candidate_file_component_members AS member ON member.canonical_file_uuid=selected.canonical_file_uuid JOIN accepted_catalog_file_size_evidence AS evidence ON evidence.file_uuid=member.file_uuid GROUP BY selected.canonical_file_uuid,evidence.byte_length EXCEPT SELECT file_uuid,byte_length FROM shared_file_sizes WHERE file_uuid IN (SELECT member.file_uuid FROM candidate_file_component_members AS member WHERE member.canonical_file_uuid IN (SELECT canonical_file_uuid FROM candidate_review_file_components WHERE decision_id=NEW.decision_id)));
SELECT RAISE(ABORT,'shared file has contradictory accepted facts') WHERE EXISTS(SELECT 1 FROM shared_file_sizes WHERE file_uuid IN (SELECT canonical_file_uuid FROM candidate_review_file_components WHERE decision_id=NEW.decision_id) GROUP BY file_uuid HAVING count(*)>1) OR EXISTS(SELECT 1 FROM shared_file_hashes AS membership JOIN hash_values AS value USING(hash_id) WHERE membership.file_uuid IN (SELECT canonical_file_uuid FROM candidate_review_file_components WHERE decision_id=NEW.decision_id) GROUP BY membership.file_uuid,value.algorithm HAVING count(*)>1);
    SELECT RAISE(ABORT,'accepted incoming hash contradicts retained file') WHERE EXISTS (
        SELECT 1 FROM file_match_decisions AS decision
        JOIN file_match_hash_decisions AS review USING(decision_id)
        JOIN candidate_qualified_file_hashes AS source USING(reported_hash_id)
        JOIN hash_values AS incoming ON incoming.hash_id=source.hash_id
        JOIN canonical_shared_file_uuids AS kept ON kept.file_uuid=decision.kept_file_uuid
        JOIN shared_file_hashes AS membership ON membership.file_uuid=kept.canonical_file_uuid
        JOIN hash_values AS retained ON retained.hash_id=membership.hash_id
        WHERE decision.decision_id=NEW.decision_id AND decision.decision='merge'
          AND review.role='incoming' AND review.disposition='accept'
          AND incoming.algorithm=retained.algorithm AND incoming.bytes<>retained.bytes
          AND NOT EXISTS (
              SELECT 1 FROM file_match_hash_decisions AS rejection
              JOIN file_match_decision_publications AS publication USING(decision_id)
              WHERE rejection.reported_hash_id=source.reported_hash_id AND rejection.disposition='reject'
          )
    );
    SELECT RAISE(ABORT,'accepted incoming size contradicts retained file') WHERE EXISTS (
        SELECT 1 FROM file_match_decisions AS decision
        JOIN file_match_size_decisions AS review USING(decision_id)
        JOIN candidate_native_file_sizes AS source
          ON source.media_entry_id=review.media_entry_id AND source.source_size_field=review.source_size_field
        JOIN candidate_native_file_byte_coverage AS qualification ON qualification.media_entry_id=source.media_entry_id
        JOIN canonical_shared_file_uuids AS kept ON kept.file_uuid=decision.kept_file_uuid
        JOIN shared_file_sizes AS retained ON retained.file_uuid=kept.canonical_file_uuid
        WHERE decision.decision_id=NEW.decision_id AND decision.decision='merge'
          AND review.role='incoming' AND review.disposition='accept' AND source.size_state='value'
          AND source.byte_length<>retained.byte_length
          AND NOT EXISTS (
              SELECT 1 FROM file_match_size_decisions AS rejection
              JOIN file_match_decision_publications AS publication USING(decision_id)
              WHERE rejection.media_entry_id=source.media_entry_id
                AND rejection.source_size_field=source.source_size_field AND rejection.disposition='reject'
          )
    );
    SELECT RAISE(ABORT,'linked incoming file is outside the merged component') WHERE EXISTS (
        SELECT 1 FROM file_match_decisions AS decision
        JOIN file_match_decision_conflicts AS settled USING(decision_id)
        JOIN file_match_conflicts AS conflict USING(conflict_id)
        JOIN catalog_media_entries AS incoming ON incoming.media_entry_id=conflict.incoming_media_entry_id
        JOIN canonical_shared_file_uuids AS incoming_root ON incoming_root.file_uuid=incoming.file_uuid
        JOIN canonical_shared_file_uuids AS kept ON kept.file_uuid=decision.kept_file_uuid
        WHERE decision.decision_id=NEW.decision_id AND decision.decision='merge'
          AND incoming_root.canonical_file_uuid<>kept.canonical_file_uuid
    );
END;

