IN (SELECT member.file_uuid FROM candidate_file_component_members AS member WHERE member.canonical_file_uuid IN (SELECT canonical.canonical_file_uuid FROM catalog_source_elements AS element JOIN catalog_media_entries AS media ON media.media_entry_id=element.source_element_id JOIN canonical_shared_file_uuids AS canonical ON canonical.file_uuid=media.file_uuid WHERE element.edition_id=NEW.edition_id)));
