INSERT INTO shared_file_sizes(file_uuid,byte_length) SELECT selected.canonical_file_uuid AS file_uuid,evidence.byte_length FROM (SELECT DISTINCT canonical_file_uuid FROM (SELECT canonical.canonical_file_uuid FROM catalog_source_elements AS element JOIN catalog_media_entries AS media ON media.media_entry_id=element.source_element_id JOIN canonical_shared_file_uuids AS canonical ON canonical.file_uuid=media.file_uuid WHERE element.edition_id=NEW.edition_id)) AS selected CROSS JOIN candidate_file_component_members AS member ON member.canonical_file_uuid=selected.canonical_file_uuid JOIN accepted_catalog_file_size_evidence AS evidence ON evidence.file_uuid=member.file_uuid GROUP BY selected.canonical_file_uuid,evidence.byte_length;
