CREATE VIEW candidate_dat_xsi_attributes AS
SELECT 'document' AS owner_kind, native.edition_id AS owner_id,
       edition.edition_id, rules.dialect, rules.format_family, xsi.field_kind, xsi.value_text,
       xsi.source_qname, NULL AS resolved_type_kind,
       NULL AS base_type_kind
FROM catalog_editions AS edition
CROSS JOIN no_intro_dat_documents AS native ON native.edition_id=edition.edition_id
CROSS JOIN no_intro_dat_document_xsi_attributes AS xsi ON xsi.edition_id=native.edition_id
CROSS JOIN catalog_reading_rules AS rules ON rules.reading_rules_id=edition.reading_rules_id UNION ALL SELECT 'header' AS owner_kind, native.header_id AS owner_id,
       edition.edition_id, rules.dialect, rules.format_family, xsi.field_kind, xsi.value_text,
       xsi.source_qname, NULL AS resolved_type_kind,
       NULL AS base_type_kind
FROM catalog_editions AS edition
CROSS JOIN catalog_source_elements AS element
  ON element.edition_id=edition.edition_id AND element.element_kind='no_intro_dat_header'
CROSS JOIN no_intro_dat_headers AS native ON native.header_id=element.source_element_id
CROSS JOIN no_intro_dat_header_xsi_attributes AS xsi ON xsi.header_id=native.header_id
CROSS JOIN catalog_reading_rules AS rules ON rules.reading_rules_id=edition.reading_rules_id UNION ALL SELECT 'header_text_child' AS owner_kind, native.source_element_id AS owner_id,
       edition.edition_id, rules.dialect, rules.format_family, xsi.field_kind, xsi.value_text,
       xsi.source_qname, xsi.resolved_type_kind AS resolved_type_kind,
       CASE WHEN native.field_kind='id' THEN 'int' ELSE 'string' END AS base_type_kind
FROM catalog_editions AS edition
CROSS JOIN catalog_source_elements AS element
  ON element.edition_id=edition.edition_id AND element.element_kind='no_intro_dat_header_text_child'
CROSS JOIN no_intro_dat_header_text_children AS native ON native.source_element_id=element.source_element_id
CROSS JOIN no_intro_dat_header_text_child_xsi_attributes AS xsi ON xsi.source_element_id=native.source_element_id
CROSS JOIN catalog_reading_rules AS rules ON rules.reading_rules_id=edition.reading_rules_id UNION ALL SELECT 'clrmamepro' AS owner_kind, native.source_element_id AS owner_id,
       edition.edition_id, rules.dialect, rules.format_family, xsi.field_kind, xsi.value_text,
       xsi.source_qname, NULL AS resolved_type_kind,
       NULL AS base_type_kind
FROM catalog_editions AS edition
CROSS JOIN catalog_source_elements AS element
  ON element.edition_id=edition.edition_id AND element.element_kind='no_intro_dat_clrmamepro'
CROSS JOIN no_intro_dat_clrmamepro_options AS native ON native.source_element_id=element.source_element_id
CROSS JOIN no_intro_dat_clrmamepro_xsi_attributes AS xsi ON xsi.source_element_id=native.source_element_id
CROSS JOIN catalog_reading_rules AS rules ON rules.reading_rules_id=edition.reading_rules_id UNION ALL SELECT 'romcenter' AS owner_kind, native.source_element_id AS owner_id,
       edition.edition_id, rules.dialect, rules.format_family, xsi.field_kind, xsi.value_text,
       xsi.source_qname, NULL AS resolved_type_kind,
       NULL AS base_type_kind
FROM catalog_editions AS edition
CROSS JOIN catalog_source_elements AS element
  ON element.edition_id=edition.edition_id AND element.element_kind='no_intro_dat_romcenter'
CROSS JOIN no_intro_dat_romcenter_options AS native ON native.source_element_id=element.source_element_id
CROSS JOIN no_intro_dat_romcenter_xsi_attributes AS xsi ON xsi.source_element_id=native.source_element_id
CROSS JOIN catalog_reading_rules AS rules ON rules.reading_rules_id=edition.reading_rules_id UNION ALL SELECT 'game' AS owner_kind, native.set_id AS owner_id,
       edition.edition_id, rules.dialect, rules.format_family, xsi.field_kind, xsi.value_text,
       xsi.source_qname, NULL AS resolved_type_kind,
       NULL AS base_type_kind
FROM catalog_editions AS edition
CROSS JOIN catalog_source_elements AS element
  ON element.edition_id=edition.edition_id AND element.element_kind='no_intro_dat_game'
CROSS JOIN no_intro_dat_games AS native ON native.set_id=element.source_element_id
CROSS JOIN no_intro_dat_game_xsi_attributes AS xsi ON xsi.set_id=native.set_id
CROSS JOIN catalog_reading_rules AS rules ON rules.reading_rules_id=edition.reading_rules_id UNION ALL SELECT 'game_description' AS owner_kind, native.source_element_id AS owner_id,
       edition.edition_id, rules.dialect, rules.format_family, xsi.field_kind, xsi.value_text,
       xsi.source_qname, xsi.resolved_type_kind AS resolved_type_kind,
       'string' AS base_type_kind
FROM catalog_editions AS edition
CROSS JOIN catalog_source_elements AS element
  ON element.edition_id=edition.edition_id AND element.element_kind='no_intro_dat_game_description'
CROSS JOIN no_intro_dat_game_descriptions AS native ON native.source_element_id=element.source_element_id
CROSS JOIN no_intro_dat_game_description_xsi_attributes AS xsi ON xsi.source_element_id=native.source_element_id
CROSS JOIN catalog_reading_rules AS rules ON rules.reading_rules_id=edition.reading_rules_id UNION ALL SELECT 'category' AS owner_kind, native.source_element_id AS owner_id,
       edition.edition_id, rules.dialect, rules.format_family, xsi.field_kind, xsi.value_text,
       xsi.source_qname, xsi.resolved_type_kind AS resolved_type_kind,
       'string' AS base_type_kind
FROM catalog_editions AS edition
CROSS JOIN catalog_source_elements AS element
  ON element.edition_id=edition.edition_id AND element.element_kind='no_intro_dat_category'
CROSS JOIN no_intro_dat_categories AS native ON native.source_element_id=element.source_element_id
CROSS JOIN no_intro_dat_category_xsi_attributes AS xsi ON xsi.source_element_id=native.source_element_id
CROSS JOIN catalog_reading_rules AS rules ON rules.reading_rules_id=edition.reading_rules_id UNION ALL SELECT 'identifier' AS owner_kind, native.source_element_id AS owner_id,
       edition.edition_id, rules.dialect, rules.format_family, xsi.field_kind, xsi.value_text,
       xsi.source_qname, xsi.resolved_type_kind AS resolved_type_kind,
       'string' AS base_type_kind
FROM catalog_editions AS edition
CROSS JOIN catalog_source_elements AS element
  ON element.edition_id=edition.edition_id AND element.element_kind='no_intro_dat_identifier'
CROSS JOIN no_intro_dat_identifiers AS native ON native.source_element_id=element.source_element_id
CROSS JOIN no_intro_dat_identifier_xsi_attributes AS xsi ON xsi.source_element_id=native.source_element_id
CROSS JOIN catalog_reading_rules AS rules ON rules.reading_rules_id=edition.reading_rules_id UNION ALL SELECT 'release' AS owner_kind, native.source_element_id AS owner_id,
       edition.edition_id, rules.dialect, rules.format_family, xsi.field_kind, xsi.value_text,
       xsi.source_qname, NULL AS resolved_type_kind,
       NULL AS base_type_kind
FROM catalog_editions AS edition
CROSS JOIN catalog_source_elements AS element
  ON element.edition_id=edition.edition_id AND element.element_kind='no_intro_dat_release'
CROSS JOIN no_intro_dat_releases AS native ON native.source_element_id=element.source_element_id
CROSS JOIN no_intro_dat_release_xsi_attributes AS xsi ON xsi.source_element_id=native.source_element_id
CROSS JOIN catalog_reading_rules AS rules ON rules.reading_rules_id=edition.reading_rules_id UNION ALL SELECT 'rom' AS owner_kind, native.media_entry_id AS owner_id,
       edition.edition_id, rules.dialect, rules.format_family, xsi.field_kind, xsi.value_text,
       xsi.source_qname, NULL AS resolved_type_kind,
       NULL AS base_type_kind
FROM catalog_editions AS edition
CROSS JOIN catalog_source_elements AS element
  ON element.edition_id=edition.edition_id AND element.element_kind='no_intro_dat_rom'
CROSS JOIN no_intro_dat_rom_claims AS native ON native.media_entry_id=element.source_element_id
CROSS JOIN no_intro_dat_rom_xsi_attributes AS xsi ON xsi.media_entry_id=native.media_entry_id
CROSS JOIN catalog_reading_rules AS rules ON rules.reading_rules_id=edition.reading_rules_id;

CREATE VIEW candidate_dat_xsi_lexical AS
SELECT *, (
WITH RECURSIVE
source(raw) AS (VALUES ((value_text))),
normalized(value) AS (
    SELECT CASE WHEN typeof(raw) = 'text'
        THEN replace(replace(replace(raw, char(9), ' '), char(10), ' '), char(13), ' ')
        ELSE raw END
    FROM source
),
collapsed(value) AS (
    SELECT trim(value, ' ') FROM normalized WHERE typeof(value) = 'text'
    UNION ALL
    SELECT replace(value, '  ', ' ')
    FROM collapsed
    WHERE instr(value, '  ') > 0
)
SELECT value FROM collapsed WHERE instr(value, '  ') = 0
UNION ALL
SELECT value FROM normalized WHERE typeof(value) <> 'text'
) AS lexical_value
FROM candidate_dat_xsi_attributes;

CREATE VIEW candidate_dat_simple_values AS
SELECT *, (
WITH RECURSIVE
source(raw) AS (VALUES ((value_text))),
normalized(value) AS (
    SELECT CASE WHEN typeof(raw) = 'text'
        THEN replace(replace(replace(raw, char(9), ' '), char(10), ' '), char(13), ' ')
        ELSE raw END
    FROM source
),
collapsed(value) AS (
    SELECT trim(value, ' ') FROM normalized WHERE typeof(value) = 'text'
    UNION ALL
    SELECT replace(value, '  ', ' ')
    FROM collapsed
    WHERE instr(value, '  ') > 0
)
SELECT value FROM collapsed WHERE instr(value, '  ') = 0
UNION ALL
SELECT value FROM normalized WHERE typeof(value) <> 'text'
) AS collapsed_text
FROM (SELECT 'header_text_child' AS owner_kind, native.source_element_id AS owner_id,
       edition.edition_id, rules.dialect, native.value_text AS value_text,
       coalesce(xsi.resolved_type_kind, CASE WHEN native.field_kind='id' THEN 'int' ELSE 'string' END) AS effective_type_kind
FROM catalog_editions AS edition
CROSS JOIN catalog_source_elements AS element
  ON element.edition_id=edition.edition_id AND element.element_kind='no_intro_dat_header_text_child'
CROSS JOIN no_intro_dat_header_text_children AS native ON native.source_element_id=element.source_element_id
LEFT JOIN no_intro_dat_header_text_child_xsi_attributes AS xsi ON xsi.source_element_id=native.source_element_id AND xsi.field_kind='type'
CROSS JOIN catalog_reading_rules AS rules ON rules.reading_rules_id=edition.reading_rules_id UNION ALL SELECT 'game_description' AS owner_kind, native.source_element_id AS owner_id,
       edition.edition_id, rules.dialect, native.description_text AS value_text,
       coalesce(xsi.resolved_type_kind, 'string') AS effective_type_kind
FROM catalog_editions AS edition
CROSS JOIN catalog_source_elements AS element
  ON element.edition_id=edition.edition_id AND element.element_kind='no_intro_dat_game_description'
CROSS JOIN no_intro_dat_game_descriptions AS native ON native.source_element_id=element.source_element_id
LEFT JOIN no_intro_dat_game_description_xsi_attributes AS xsi ON xsi.source_element_id=native.source_element_id AND xsi.field_kind='type'
CROSS JOIN catalog_reading_rules AS rules ON rules.reading_rules_id=edition.reading_rules_id UNION ALL SELECT 'category' AS owner_kind, native.source_element_id AS owner_id,
       edition.edition_id, rules.dialect, native.category AS value_text,
       coalesce(xsi.resolved_type_kind, 'string') AS effective_type_kind
FROM catalog_editions AS edition
CROSS JOIN catalog_source_elements AS element
  ON element.edition_id=edition.edition_id AND element.element_kind='no_intro_dat_category'
CROSS JOIN no_intro_dat_categories AS native ON native.source_element_id=element.source_element_id
LEFT JOIN no_intro_dat_category_xsi_attributes AS xsi ON xsi.source_element_id=native.source_element_id AND xsi.field_kind='type'
CROSS JOIN catalog_reading_rules AS rules ON rules.reading_rules_id=edition.reading_rules_id UNION ALL SELECT 'identifier' AS owner_kind, native.source_element_id AS owner_id,
       edition.edition_id, rules.dialect, native.identifier AS value_text,
       coalesce(xsi.resolved_type_kind, 'string') AS effective_type_kind
FROM catalog_editions AS edition
CROSS JOIN catalog_source_elements AS element
  ON element.edition_id=edition.edition_id AND element.element_kind='no_intro_dat_identifier'
CROSS JOIN no_intro_dat_identifiers AS native ON native.source_element_id=element.source_element_id
LEFT JOIN no_intro_dat_identifier_xsi_attributes AS xsi ON xsi.source_element_id=native.source_element_id AND xsi.field_kind='type'
CROSS JOIN catalog_reading_rules AS rules ON rules.reading_rules_id=edition.reading_rules_id);

-- A single partitioned pass avoids replicating a grouped ID materialization
-- for each native UNION branch. Edition is a partition key, so an outer
-- edition filter can move below the window without changing its result.
CREATE VIEW candidate_dat_identity_problems AS
SELECT CASE WHEN effective_type_kind='ID' THEN 'dat_xsi_duplicate_id'
            ELSE 'dat_xsi_unresolved_idref' END AS problem,owner_id,edition_id
FROM (
    SELECT owner_id,edition_id,effective_type_kind,
           sum(effective_type_kind='ID') OVER (
               PARTITION BY edition_id,collapsed_text COLLATE BINARY
           ) AS declarations
    FROM candidate_dat_simple_values
    WHERE dialect IN ('no-intro-dat-v3-strict','no-intro-dat-v4-strict') AND effective_type_kind IN ('ID','IDREF')
)
WHERE (effective_type_kind='ID' AND declarations>1)
   OR (effective_type_kind='IDREF' AND declarations=0);

CREATE VIEW candidate_dat_xsi_declaration_problems AS
SELECT 'dat_xsi_reading_rules' AS problem,owner_kind,owner_id,edition_id,field_kind FROM candidate_dat_xsi_lexical WHERE format_family IS NOT 'no_intro_dat' OR dialect NOT IN ('no-intro-dat-v3-strict','no-intro-dat-v3-compatible','no-intro-dat-v4-strict','no-intro-dat-v4-compatible') UNION ALL SELECT 'dat_xsi_source_qname' AS problem,owner_kind,owner_id,edition_id,field_kind FROM candidate_dat_xsi_lexical WHERE NOT ((
WITH source(value) AS (VALUES ((source_qname)))
SELECT CASE
    WHEN typeof(value) <> 'text' OR length(value) = 0
      OR instr(CAST(value AS BLOB), X'00') <> 0 THEN 0
    WHEN instr(value, ':') = 0 THEN CASE WHEN (typeof(value) = 'text' AND length(value) > 0 AND instr(CAST(value AS BLOB), X'00') = 0 AND (value) NOT GLOB '*[^--.0-9A-Z_a-z·À-ÖØ-öø-˿̀-ͯͰ-ͽͿ-῿‌-‍‿-⁀⁰-↏Ⰰ-⿯、-퟿豈-﷏ﷰ-�𐀀-󯿿]*' AND instr(CAST(value AS BLOB), X'EFBFBE') = 0 AND instr(CAST(value AS BLOB), X'EFBFBF') = 0 AND substr(value, 1, 1) GLOB '[A-Z_a-zÀ-ÖØ-öø-˿Ͱ-ͽͿ-῿‌-‍⁰-↏Ⰰ-⿯、-퟿豈-﷏ﷰ-�𐀀-󯿿]') THEN 1 ELSE 0 END
    WHEN instr(substr(value, instr(value, ':') + 1), ':') <> 0 THEN 0
    WHEN (typeof(substr(value, 1, instr(value, ':') - 1)) = 'text' AND length(substr(value, 1, instr(value, ':') - 1)) > 0 AND instr(CAST(substr(value, 1, instr(value, ':') - 1) AS BLOB), X'00') = 0 AND (substr(value, 1, instr(value, ':') - 1)) NOT GLOB '*[^--.0-9A-Z_a-z·À-ÖØ-öø-˿̀-ͯͰ-ͽͿ-῿‌-‍‿-⁀⁰-↏Ⰰ-⿯、-퟿豈-﷏ﷰ-�𐀀-󯿿]*' AND instr(CAST(substr(value, 1, instr(value, ':') - 1) AS BLOB), X'EFBFBE') = 0 AND instr(CAST(substr(value, 1, instr(value, ':') - 1) AS BLOB), X'EFBFBF') = 0 AND substr(substr(value, 1, instr(value, ':') - 1), 1, 1) GLOB '[A-Z_a-zÀ-ÖØ-öø-˿Ͱ-ͽͿ-῿‌-‍⁰-↏Ⰰ-⿯、-퟿豈-﷏ﷰ-�𐀀-󯿿]') AND (typeof(substr(value, instr(value, ':') + 1)) = 'text' AND length(substr(value, instr(value, ':') + 1)) > 0 AND instr(CAST(substr(value, instr(value, ':') + 1) AS BLOB), X'00') = 0 AND (substr(value, instr(value, ':') + 1)) NOT GLOB '*[^--.0-9A-Z_a-z·À-ÖØ-öø-˿̀-ͯͰ-ͽͿ-῿‌-‍‿-⁀⁰-↏Ⰰ-⿯、-퟿豈-﷏ﷰ-�𐀀-󯿿]*' AND instr(CAST(substr(value, instr(value, ':') + 1) AS BLOB), X'EFBFBE') = 0 AND instr(CAST(substr(value, instr(value, ':') + 1) AS BLOB), X'EFBFBF') = 0 AND substr(substr(value, instr(value, ':') + 1), 1, 1) GLOB '[A-Z_a-zÀ-ÖØ-öø-˿Ͱ-ͽͿ-῿‌-‍⁰-↏Ⰰ-⿯、-퟿豈-﷏ﷰ-�𐀀-󯿿]') THEN 1
    ELSE 0
END
FROM source
)) OR instr(source_qname,':')=0 OR substr(source_qname,instr(source_qname,':')+1) IS NOT field_kind UNION ALL SELECT 'dat_xsi_value_nul' AS problem,owner_kind,owner_id,edition_id,field_kind FROM candidate_dat_xsi_lexical WHERE instr(CAST(value_text AS BLOB),X'00')>0 UNION ALL SELECT 'dat_xsi_nil' AS problem,owner_kind,owner_id,edition_id,field_kind FROM candidate_dat_xsi_lexical WHERE field_kind='nil' AND (dialect IN ('no-intro-dat-v3-strict','no-intro-dat-v4-strict') OR lexical_value NOT IN ('false','0')) UNION ALL SELECT 'dat_xsi_type' AS problem,owner_kind,owner_id,edition_id,field_kind FROM candidate_dat_xsi_lexical WHERE field_kind='type' AND (
             NOT ((
WITH source(value) AS (VALUES ((lexical_value)))
SELECT CASE
    WHEN typeof(value) <> 'text' OR length(value) = 0
      OR instr(CAST(value AS BLOB), X'00') <> 0 THEN 0
    WHEN instr(value, ':') = 0 THEN CASE WHEN (typeof(value) = 'text' AND length(value) > 0 AND instr(CAST(value AS BLOB), X'00') = 0 AND (value) NOT GLOB '*[^--.0-9A-Z_a-z·À-ÖØ-öø-˿̀-ͯͰ-ͽͿ-῿‌-‍‿-⁀⁰-↏Ⰰ-⿯、-퟿豈-﷏ﷰ-�𐀀-󯿿]*' AND instr(CAST(value AS BLOB), X'EFBFBE') = 0 AND instr(CAST(value AS BLOB), X'EFBFBF') = 0 AND substr(value, 1, 1) GLOB '[A-Z_a-zÀ-ÖØ-öø-˿Ͱ-ͽͿ-῿‌-‍⁰-↏Ⰰ-⿯、-퟿豈-﷏ﷰ-�𐀀-󯿿]') THEN 1 ELSE 0 END
    WHEN instr(substr(value, instr(value, ':') + 1), ':') <> 0 THEN 0
    WHEN (typeof(substr(value, 1, instr(value, ':') - 1)) = 'text' AND length(substr(value, 1, instr(value, ':') - 1)) > 0 AND instr(CAST(substr(value, 1, instr(value, ':') - 1) AS BLOB), X'00') = 0 AND (substr(value, 1, instr(value, ':') - 1)) NOT GLOB '*[^--.0-9A-Z_a-z·À-ÖØ-öø-˿̀-ͯͰ-ͽͿ-῿‌-‍‿-⁀⁰-↏Ⰰ-⿯、-퟿豈-﷏ﷰ-�𐀀-󯿿]*' AND instr(CAST(substr(value, 1, instr(value, ':') - 1) AS BLOB), X'EFBFBE') = 0 AND instr(CAST(substr(value, 1, instr(value, ':') - 1) AS BLOB), X'EFBFBF') = 0 AND substr(substr(value, 1, instr(value, ':') - 1), 1, 1) GLOB '[A-Z_a-zÀ-ÖØ-öø-˿Ͱ-ͽͿ-῿‌-‍⁰-↏Ⰰ-⿯、-퟿豈-﷏ﷰ-�𐀀-󯿿]') AND (typeof(substr(value, instr(value, ':') + 1)) = 'text' AND length(substr(value, instr(value, ':') + 1)) > 0 AND instr(CAST(substr(value, instr(value, ':') + 1) AS BLOB), X'00') = 0 AND (substr(value, instr(value, ':') + 1)) NOT GLOB '*[^--.0-9A-Z_a-z·À-ÖØ-öø-˿̀-ͯͰ-ͽͿ-῿‌-‍‿-⁀⁰-↏Ⰰ-⿯、-퟿豈-﷏ﷰ-�𐀀-󯿿]*' AND instr(CAST(substr(value, instr(value, ':') + 1) AS BLOB), X'EFBFBE') = 0 AND instr(CAST(substr(value, instr(value, ':') + 1) AS BLOB), X'EFBFBF') = 0 AND substr(substr(value, instr(value, ':') + 1), 1, 1) GLOB '[A-Z_a-zÀ-ÖØ-öø-˿Ͱ-ͽͿ-῿‌-‍⁰-↏Ⰰ-⿯、-퟿豈-﷏ﷰ-�𐀀-󯿿]') THEN 1
    ELSE 0
END
FROM source
))
             OR substr(lexical_value,instr(lexical_value,':')+1) IS NOT resolved_type_kind
             OR CASE base_type_kind
                  WHEN 'int' THEN resolved_type_kind NOT IN ('int','short','byte')
                  WHEN 'string' THEN resolved_type_kind NOT IN ('string','normalizedString','token','language','Name','NCName','NMTOKEN','ID','IDREF','ENTITY') ELSE 1 END)
UNION ALL
SELECT hint_problem,owner_kind,owner_id,edition_id,field_kind
FROM (SELECT owner_kind,owner_id,edition_id,field_kind,
             (
WITH RECURSIVE input(value,field,dialect) AS NOT MATERIALIZED (VALUES (lexical_value,field_kind,dialect)),
tokens(ordinal,token,rest) AS (
    SELECT 0,'',CASE WHEN field='schemaLocation' THEN value ELSE '' END FROM input
    UNION ALL
    SELECT ordinal+1,substr(rest,1,instr(rest||' ',' ')-1),substr(rest,instr(rest||' ',' ')+1)
    FROM tokens WHERE rest<>''
),
locations(location) AS (
    SELECT token FROM tokens WHERE ordinal>0 AND ordinal%2=0
    UNION ALL
    SELECT value FROM input WHERE field='noNamespaceSchemaLocation'
),
revisions(revision) AS (
    SELECT CASE WHEN core='schema_nointro_datfile_v3.xsd' OR substr(core,-30) IN ('/schema_nointro_datfile_v3.xsd',char(92)||'schema_nointro_datfile_v3.xsd') THEN 3 WHEN core='schema_nointro_datfile_v4.xsd' OR substr(core,-30) IN ('/schema_nointro_datfile_v4.xsd',char(92)||'schema_nointro_datfile_v4.xsd') THEN 4 END
    FROM (SELECT substr(location,1,min(instr(location||'?', '?'),instr(location||'#', '#'))-1) AS core FROM locations)
)
SELECT CASE
    WHEN (SELECT count(*) FROM tokens WHERE ordinal>0)%2<>0 THEN 'dat_xsi_schema_pairs'
    WHEN EXISTS (SELECT 1 FROM revisions WHERE revision IS NOT NULL AND revision<>
                 CASE WHEN dialect IN ('no-intro-dat-v3-strict','no-intro-dat-v3-compatible') THEN 3 ELSE 4 END)
    THEN 'dat_xsi_schema_revision'
END FROM input
) AS hint_problem
      FROM candidate_dat_xsi_lexical WHERE field_kind IN ('schemaLocation','noNamespaceSchemaLocation'))
WHERE hint_problem IS NOT NULL;

CREATE VIEW candidate_dat_xsi_problems AS
SELECT problem,owner_id,edition_id FROM candidate_dat_xsi_declaration_problems
UNION ALL
SELECT 'dat_xsi_simple_value',owner_id,edition_id
FROM candidate_dat_simple_values
WHERE dialect IN ('no-intro-dat-v3-strict','no-intro-dat-v4-strict') AND NOT (CASE effective_type_kind
WHEN 'int' THEN (
WITH
source(raw) AS NOT MATERIALIZED (VALUES ((value_text))),
trimmed(value) AS (
    SELECT trim(raw, char(9) || char(10) || char(13) || ' ')
    FROM source
    WHERE typeof(raw) = 'text'
      AND instr(CAST(raw AS BLOB), X'00') = 0
),
signed(value, negative, digits) AS (
    SELECT value,
           substr(value, 1, 1) = '-',
           CASE WHEN substr(value, 1, 1) IN ('+', '-')
                THEN substr(value, 2) ELSE value END
    FROM trimmed
),
parsed(negative, significant) AS (
    SELECT negative, coalesce(nullif(ltrim(digits, '0'), ''), '0')
    FROM signed
    WHERE digits <> '' AND digits NOT GLOB '*[^0-9]*'
),
accepted(negative, significant) AS (
    SELECT negative, significant
    FROM parsed
    WHERE CASE
        WHEN significant = '0' THEN 1
        WHEN negative THEN ((length(significant) < length('2147483648') OR (length(significant) = length('2147483648') AND significant COLLATE BINARY <= '2147483648'))) AND (1)
        ELSE (1) AND ((length(significant) < length('2147483647') OR (length(significant) = length('2147483647') AND significant COLLATE BINARY <= '2147483647')))
    END
)
SELECT CASE
    WHEN significant = '0' THEN 0
    WHEN negative THEN CASE WHEN significant = '9223372036854775808' THEN (-9223372036854775807 - 1) ELSE -CAST(significant AS INTEGER) END
    ELSE CAST(significant AS INTEGER)
END
FROM accepted
) IS NOT NULL WHEN 'short' THEN (
WITH
source(raw) AS NOT MATERIALIZED (VALUES ((value_text))),
trimmed(value) AS (
    SELECT trim(raw, char(9) || char(10) || char(13) || ' ')
    FROM source
    WHERE typeof(raw) = 'text'
      AND instr(CAST(raw AS BLOB), X'00') = 0
),
signed(value, negative, digits) AS (
    SELECT value,
           substr(value, 1, 1) = '-',
           CASE WHEN substr(value, 1, 1) IN ('+', '-')
                THEN substr(value, 2) ELSE value END
    FROM trimmed
),
parsed(negative, significant) AS (
    SELECT negative, coalesce(nullif(ltrim(digits, '0'), ''), '0')
    FROM signed
    WHERE digits <> '' AND digits NOT GLOB '*[^0-9]*'
),
accepted(negative, significant) AS (
    SELECT negative, significant
    FROM parsed
    WHERE CASE
        WHEN significant = '0' THEN 1
        WHEN negative THEN ((length(significant) < length('32768') OR (length(significant) = length('32768') AND significant COLLATE BINARY <= '32768'))) AND (1)
        ELSE (1) AND ((length(significant) < length('32767') OR (length(significant) = length('32767') AND significant COLLATE BINARY <= '32767')))
    END
)
SELECT CASE
    WHEN significant = '0' THEN 0
    WHEN negative THEN CASE WHEN significant = '9223372036854775808' THEN (-9223372036854775807 - 1) ELSE -CAST(significant AS INTEGER) END
    ELSE CAST(significant AS INTEGER)
END
FROM accepted
) IS NOT NULL WHEN 'byte' THEN (
WITH
source(raw) AS NOT MATERIALIZED (VALUES ((value_text))),
trimmed(value) AS (
    SELECT trim(raw, char(9) || char(10) || char(13) || ' ')
    FROM source
    WHERE typeof(raw) = 'text'
      AND instr(CAST(raw AS BLOB), X'00') = 0
),
signed(value, negative, digits) AS (
    SELECT value,
           substr(value, 1, 1) = '-',
           CASE WHEN substr(value, 1, 1) IN ('+', '-')
                THEN substr(value, 2) ELSE value END
    FROM trimmed
),
parsed(negative, significant) AS (
    SELECT negative, coalesce(nullif(ltrim(digits, '0'), ''), '0')
    FROM signed
    WHERE digits <> '' AND digits NOT GLOB '*[^0-9]*'
),
accepted(negative, significant) AS (
    SELECT negative, significant
    FROM parsed
    WHERE CASE
        WHEN significant = '0' THEN 1
        WHEN negative THEN ((length(significant) < length('128') OR (length(significant) = length('128') AND significant COLLATE BINARY <= '128'))) AND (1)
        ELSE (1) AND ((length(significant) < length('127') OR (length(significant) = length('127') AND significant COLLATE BINARY <= '127')))
    END
)
SELECT CASE
    WHEN significant = '0' THEN 0
    WHEN negative THEN CASE WHEN significant = '9223372036854775808' THEN (-9223372036854775807 - 1) ELSE -CAST(significant AS INTEGER) END
    ELSE CAST(significant AS INTEGER)
END
FROM accepted
) IS NOT NULL WHEN 'string' THEN 1 WHEN 'normalizedString' THEN 1 WHEN 'token' THEN 1 WHEN 'language' THEN (
WITH RECURSIVE
source(value) AS (VALUES ((collapsed_text))),
parts(segment, rest, ordinal) AS (
    SELECT
        CASE WHEN instr(value, '-') = 0 THEN value
             ELSE substr(value, 1, instr(value, '-') - 1) END,
        CASE WHEN instr(value, '-') = 0 THEN NULL
             ELSE substr(value, instr(value, '-') + 1) END,
        0
    FROM source
    WHERE typeof(value) = 'text'
      AND length(value) > 0
      AND instr(CAST(value AS BLOB), X'00') = 0
    UNION ALL
    SELECT
        CASE WHEN instr(rest, '-') = 0 THEN rest
             ELSE substr(rest, 1, instr(rest, '-') - 1) END,
        CASE WHEN instr(rest, '-') = 0 THEN NULL
             ELSE substr(rest, instr(rest, '-') + 1) END,
        ordinal + 1
    FROM parts
    WHERE rest IS NOT NULL
),
checked(ok) AS (
    SELECT count(*) > 0 AND min(
        length(segment) BETWEEN 1 AND 8
        AND segment NOT GLOB CASE WHEN ordinal = 0
            THEN '*[^A-Za-z]*' ELSE '*[^A-Za-z0-9]*' END
    )
    FROM parts
)
SELECT CASE WHEN coalesce((SELECT ok FROM checked), 0) THEN 1 ELSE 0 END
) WHEN 'Name' THEN (
WITH source(value) AS (VALUES ((collapsed_text)))
SELECT CASE WHEN coalesce((typeof(value) = 'text' AND length(value) > 0 AND instr(CAST(value AS BLOB), X'00') = 0 AND (value) NOT GLOB '*[^--.0-9A-Z_a-z·À-ÖØ-öø-˿̀-ͯͰ-ͽͿ-῿‌-‍‿-⁀⁰-↏Ⰰ-⿯、-퟿豈-﷏ﷰ-�𐀀-󯿿:]*' AND instr(CAST(value AS BLOB), X'EFBFBE') = 0 AND instr(CAST(value AS BLOB), X'EFBFBF') = 0 AND substr(value, 1, 1) GLOB '[A-Z_a-zÀ-ÖØ-öø-˿Ͱ-ͽͿ-῿‌-‍⁰-↏Ⰰ-⿯、-퟿豈-﷏ﷰ-�𐀀-󯿿:]'), 0) THEN 1 ELSE 0 END
FROM source
) WHEN 'NMTOKEN' THEN (
WITH source(value) AS (VALUES ((collapsed_text)))
SELECT CASE WHEN coalesce((typeof(value) = 'text' AND length(value) > 0 AND instr(CAST(value AS BLOB), X'00') = 0 AND (value) NOT GLOB '*[^--.0-9A-Z_a-z·À-ÖØ-öø-˿̀-ͯͰ-ͽͿ-῿‌-‍‿-⁀⁰-↏Ⰰ-⿯、-퟿豈-﷏ﷰ-�𐀀-󯿿:]*' AND instr(CAST(value AS BLOB), X'EFBFBE') = 0 AND instr(CAST(value AS BLOB), X'EFBFBF') = 0), 0) THEN 1 ELSE 0 END
FROM source
) WHEN 'NCName' THEN (
WITH source(value) AS (VALUES ((collapsed_text)))
SELECT CASE WHEN coalesce((typeof(value) = 'text' AND length(value) > 0 AND instr(CAST(value AS BLOB), X'00') = 0 AND (value) NOT GLOB '*[^--.0-9A-Z_a-z·À-ÖØ-öø-˿̀-ͯͰ-ͽͿ-῿‌-‍‿-⁀⁰-↏Ⰰ-⿯、-퟿豈-﷏ﷰ-�𐀀-󯿿]*' AND instr(CAST(value AS BLOB), X'EFBFBE') = 0 AND instr(CAST(value AS BLOB), X'EFBFBF') = 0 AND substr(value, 1, 1) GLOB '[A-Z_a-zÀ-ÖØ-öø-˿Ͱ-ͽͿ-῿‌-‍⁰-↏Ⰰ-⿯、-퟿豈-﷏ﷰ-�𐀀-󯿿]'), 0) THEN 1 ELSE 0 END
FROM source
) WHEN 'ID' THEN (
WITH source(value) AS (VALUES ((collapsed_text)))
SELECT CASE WHEN coalesce((typeof(value) = 'text' AND length(value) > 0 AND instr(CAST(value AS BLOB), X'00') = 0 AND (value) NOT GLOB '*[^--.0-9A-Z_a-z·À-ÖØ-öø-˿̀-ͯͰ-ͽͿ-῿‌-‍‿-⁀⁰-↏Ⰰ-⿯、-퟿豈-﷏ﷰ-�𐀀-󯿿]*' AND instr(CAST(value AS BLOB), X'EFBFBE') = 0 AND instr(CAST(value AS BLOB), X'EFBFBF') = 0 AND substr(value, 1, 1) GLOB '[A-Z_a-zÀ-ÖØ-öø-˿Ͱ-ͽͿ-῿‌-‍⁰-↏Ⰰ-⿯、-퟿豈-﷏ﷰ-�𐀀-󯿿]'), 0) THEN 1 ELSE 0 END
FROM source
) WHEN 'IDREF' THEN (
WITH source(value) AS (VALUES ((collapsed_text)))
SELECT CASE WHEN coalesce((typeof(value) = 'text' AND length(value) > 0 AND instr(CAST(value AS BLOB), X'00') = 0 AND (value) NOT GLOB '*[^--.0-9A-Z_a-z·À-ÖØ-öø-˿̀-ͯͰ-ͽͿ-῿‌-‍‿-⁀⁰-↏Ⰰ-⿯、-퟿豈-﷏ﷰ-�𐀀-󯿿]*' AND instr(CAST(value AS BLOB), X'EFBFBE') = 0 AND instr(CAST(value AS BLOB), X'EFBFBF') = 0 AND substr(value, 1, 1) GLOB '[A-Z_a-zÀ-ÖØ-öø-˿Ͱ-ͽͿ-῿‌-‍⁰-↏Ⰰ-⿯、-퟿豈-﷏ﷰ-�𐀀-󯿿]'), 0) THEN 1 ELSE 0 END
FROM source
) WHEN 'ENTITY' THEN 0 ELSE 0 END)
UNION ALL
SELECT * FROM candidate_dat_identity_problems;
CREATE TRIGGER candidate_dat_xsi_document_insert
AFTER INSERT ON no_intro_dat_document_xsi_attributes
WHEN EXISTS (SELECT 1 FROM (SELECT *,(
WITH RECURSIVE
source(raw) AS (VALUES ((value_text))),
normalized(value) AS (
    SELECT CASE WHEN typeof(raw) = 'text'
        THEN replace(replace(replace(raw, char(9), ' '), char(10), ' '), char(13), ' ')
        ELSE raw END
    FROM source
),
collapsed(value) AS (
    SELECT trim(value, ' ') FROM normalized WHERE typeof(value) = 'text'
    UNION ALL
    SELECT replace(value, '  ', ' ')
    FROM collapsed
    WHERE instr(value, '  ') > 0
)
SELECT value FROM collapsed WHERE instr(value, '  ') = 0
UNION ALL
SELECT value FROM normalized WHERE typeof(value) <> 'text'
) AS lexical_value FROM (SELECT NEW.field_kind AS field_kind,NEW.value_text AS value_text,
                   NEW.source_qname AS source_qname,NULL AS resolved_type_kind,
                   NULL AS base_type_kind,rules.dialect,rules.format_family
            FROM no_intro_dat_documents AS native
            JOIN catalog_editions AS edition ON edition.edition_id=native.edition_id
            JOIN catalog_reading_rules AS rules ON rules.reading_rules_id=edition.reading_rules_id
            WHERE native.edition_id=NEW.edition_id)) WHERE (format_family IS NOT 'no_intro_dat' OR dialect NOT IN ('no-intro-dat-v3-strict','no-intro-dat-v3-compatible','no-intro-dat-v4-strict','no-intro-dat-v4-compatible')) OR (NOT ((
WITH source(value) AS (VALUES ((source_qname)))
SELECT CASE
    WHEN typeof(value) <> 'text' OR length(value) = 0
      OR instr(CAST(value AS BLOB), X'00') <> 0 THEN 0
