    WHEN (typeof(substr(value, 1, instr(value, ':') - 1)) = 'text' AND length(substr(value, 1, instr(value, ':') - 1)) > 0 AND instr(CAST(substr(value, 1, instr(value, ':') - 1) AS BLOB), X'00') = 0 AND (substr(value, 1, instr(value, ':') - 1)) NOT GLOB '*[^--.0-9A-Z_a-z·À-ÖØ-öø-˿̀-ͯͰ-ͽͿ-῿‌-‍‿-⁀⁰-↏Ⰰ-⿯、-퟿豈-﷏ﷰ-�𐀀-󯿿]*' AND instr(CAST(substr(value, 1, instr(value, ':') - 1) AS BLOB), X'EFBFBE') = 0 AND instr(CAST(substr(value, 1, instr(value, ':') - 1) AS BLOB), X'EFBFBF') = 0 AND substr(substr(value, 1, instr(value, ':') - 1), 1, 1) GLOB '[A-Z_a-zÀ-ÖØ-öø-˿Ͱ-ͽͿ-῿‌-‍⁰-↏Ⰰ-⿯、-퟿豈-﷏ﷰ-�𐀀-󯿿]') AND (typeof(substr(value, instr(value, ':') + 1)) = 'text' AND length(substr(value, instr(value, ':') + 1)) > 0 AND instr(CAST(substr(value, instr(value, ':') + 1) AS BLOB), X'00') = 0 AND (substr(value, instr(value, ':') + 1)) NOT GLOB '*[^--.0-9A-Z_a-z·À-ÖØ-öø-˿̀-ͯͰ-ͽͿ-῿‌-‍‿-⁀⁰-↏Ⰰ-⿯、-퟿豈-﷏ﷰ-�𐀀-󯿿]*' AND instr(CAST(substr(value, instr(value, ':') + 1) AS BLOB), X'EFBFBE') = 0 AND instr(CAST(substr(value, instr(value, ':') + 1) AS BLOB), X'EFBFBF') = 0 AND substr(substr(value, instr(value, ':') + 1), 1, 1) GLOB '[A-Z_a-zÀ-ÖØ-öø-˿Ͱ-ͽͿ-῿‌-‍⁰-↏Ⰰ-⿯、-퟿豈-﷏ﷰ-�𐀀-󯿿]') THEN 1
    ELSE 0
END
FROM source
)) OR instr(source_qname,':')=0 OR substr(source_qname,instr(source_qname,':')+1) IS NOT field_kind) OR (instr(CAST(value_text AS BLOB),X'00')>0) OR (field_kind='nil' AND (dialect IN ('no-intro-dat-v3-strict','no-intro-dat-v4-strict') OR lexical_value NOT IN ('false','0'))) OR (field_kind='type' AND (
             NOT ((
WITH source(value) AS (VALUES ((lexical_value)))
SELECT CASE
    WHEN typeof(value) <> 'text' OR length(value) = 0
      OR instr(CAST(value AS BLOB), X'00') <> 0 THEN 0
    WHEN instr(value, ':') = 0 THEN CASE WHEN (typeof(value) = 'text' AND length(value) > 0 AND instr(CAST(value AS BLOB), X'00') = 0 AND (value) NOT GLOB '*[^--.0-9A-Z_a-z·À-ÖØ-öø-˿̀-ͯͰ-ͽͿ-῿‌-‍‿-⁀⁰-↏Ⰰ-⿯、-퟿豈-﷏ﷰ-�𐀀-󯿿]*' AND instr(CAST(value AS BLOB), X'EFBFBE') = 0 AND instr(CAST(value AS BLOB), X'EFBFBF') = 0 AND substr(value, 1, 1) GLOB '[A-Z_a-zÀ-ÖØ-öø-˿Ͱ-ͽͿ-῿‌-‍⁰-↏Ⰰ-⿯、-퟿豈-﷏ﷰ-�𐀀-󯿿]') THEN 1 ELSE 0 END
    WHEN instr(substr(value, instr(value, ':') + 1), ':') <> 0 THEN 0
    WHEN (typeof(substr(value, 1, instr(value, ':') - 1)) = 'text' AND length(substr(value, 1, instr(value, ':') - 1)) > 0 AND instr(CAST(substr(value, 1, instr(value, ':') - 1) AS BLOB), X'00') = 0 AND (substr(value, 1, instr(value, ':') - 1)) NOT GLOB '*[^--.0-9A-Z_a-z·À-ÖØ-öø-˿̀-ͯͰ-ͽͿ-῿‌-‍‿-⁀⁰-↏Ⰰ-⿯、-퟿豈-﷏ﷰ-�𐀀-󯿿]*' AND instr(CAST(substr(value, 1, instr(value, ':') - 1) AS BLOB), X'EFBFBE') = 0 AND instr(CAST(substr(value, 1, instr(value, ':') - 1) AS BLOB), X'EFBFBF') = 0 AND substr(substr(value, 1, instr(value, ':') - 1), 1, 1) GLOB '[A-Z_a-zÀ-ÖØ-öø-˿Ͱ-ͽͿ-῿‌-‍⁰-↏Ⰰ-⿯、-퟿豈-﷏ﷰ-�𐀀-󯿿]') AND (typeof(substr(value, instr(value, ':') + 1)) = 'text' AND length(substr(value, instr(value, ':') + 1)) > 0 AND instr(CAST(substr(value, instr(value, ':') + 1) AS BLOB), X'00') = 0 AND (substr(value, instr(value, ':') + 1)) NOT GLOB '*[^--.0-9A-Z_a-z·À-ÖØ-öø-˿̀-ͯͰ-ͽͿ-῿‌-‍‿-⁀⁰-↏Ⰰ-⿯、-퟿豈-﷏ﷰ-�𐀀-󯿿]*' AND instr(CAST(substr(value, instr(value, ':') + 1) AS BLOB), X'EFBFBE') = 0 AND instr(CAST(substr(value, instr(value, ':') + 1) AS BLOB), X'EFBFBF') = 0 AND substr(substr(value, instr(value, ':') + 1), 1, 1) GLOB '[A-Z_a-zÀ-ÖØ-öø-˿Ͱ-ͽͿ-῿‌-‍⁰-↏Ⰰ-⿯、-퟿豈-﷏ﷰ-�𐀀-󯿿]') THEN 1
    ELSE 0
END
FROM source
))
             OR substr(lexical_value,instr(lexical_value,':')+1) IS NOT resolved_type_kind
             OR CASE base_type_kind
                  WHEN 'int' THEN resolved_type_kind NOT IN ('int','short','byte')
                  WHEN 'string' THEN resolved_type_kind NOT IN ('string','normalizedString','token','language','Name','NCName','NMTOKEN','ID','IDREF','ENTITY') ELSE 1 END)) OR CASE WHEN field_kind IN ('schemaLocation','noNamespaceSchemaLocation') THEN (
WITH RECURSIVE input(value,field,dialect) AS NOT MATERIALIZED (VALUES (lexical_value,field_kind,dialect)),
tokens(ordinal,token,rest) AS (
    SELECT 0,'',CASE WHEN field='schemaLocation' THEN value ELSE '' END FROM input
    UNION ALL
    SELECT ordinal+1,substr(rest,1,instr(rest||' ',' ')-1),substr(rest,instr(rest||' ',' ')+1)
    FROM tokens WHERE rest<>''
),
locations(location) AS (
    SELECT token FROM tokens WHERE ordinal>0 AND ordinal%2=0
    UNION ALL
    SELECT value FROM input WHERE field='noNamespaceSchemaLocation'
),
revisions(revision) AS (
    SELECT CASE WHEN core='schema_nointro_datfile_v3.xsd' OR substr(core,-30) IN ('/schema_nointro_datfile_v3.xsd',char(92)||'schema_nointro_datfile_v3.xsd') THEN 3 WHEN core='schema_nointro_datfile_v4.xsd' OR substr(core,-30) IN ('/schema_nointro_datfile_v4.xsd',char(92)||'schema_nointro_datfile_v4.xsd') THEN 4 END
    FROM (SELECT substr(location,1,min(instr(location||'?', '?'),instr(location||'#', '#'))-1) AS core FROM locations)
)
SELECT CASE
    WHEN (SELECT count(*) FROM tokens WHERE ordinal>0)%2<>0 THEN 'dat_xsi_schema_pairs'
    WHEN EXISTS (SELECT 1 FROM revisions WHERE revision IS NOT NULL AND revision<>
                 CASE WHEN dialect IN ('no-intro-dat-v3-strict','no-intro-dat-v3-compatible') THEN 3 ELSE 4 END)
    THEN 'dat_xsi_schema_revision'
END FROM input
) IS NOT NULL ELSE 0 END)
BEGIN SELECT RAISE(ABORT,'candidate invalid DAT XSI declaration'); END;
CREATE TABLE "mame_root_import_messages"(message_id INTEGER NOT NULL,edition_id INTEGER NOT NULL,role TEXT NOT NULL CHECK(role IN ('primary','related')),PRIMARY KEY(message_id,edition_id,role),FOREIGN KEY(message_id,edition_id) REFERENCES catalog_import_messages(message_id,edition_id),FOREIGN KEY(edition_id) REFERENCES "mame_documents"(edition_id)) STRICT, WITHOUT ROWID;
CREATE TABLE "logiqx_datafile_import_messages"(message_id INTEGER NOT NULL,edition_id INTEGER NOT NULL,role TEXT NOT NULL CHECK(role IN ('primary','related')),PRIMARY KEY(message_id,edition_id,role),FOREIGN KEY(message_id,edition_id) REFERENCES catalog_import_messages(message_id,edition_id),FOREIGN KEY(edition_id) REFERENCES "logiqx_documents"(edition_id)) STRICT, WITHOUT ROWID;
CREATE TABLE "clrmamepro_document_import_messages"(message_id INTEGER NOT NULL,edition_id INTEGER NOT NULL,role TEXT NOT NULL CHECK(role IN ('primary','related')),PRIMARY KEY(message_id,edition_id,role),FOREIGN KEY(message_id,edition_id) REFERENCES catalog_import_messages(message_id,edition_id),FOREIGN KEY(edition_id) REFERENCES "clrmamepro_documents"(edition_id)) STRICT, WITHOUT ROWID;
CREATE TABLE "software_document_import_messages"(message_id INTEGER NOT NULL,edition_id INTEGER NOT NULL,role TEXT NOT NULL CHECK(role IN ('primary','related')),PRIMARY KEY(message_id,edition_id,role),FOREIGN KEY(message_id,edition_id) REFERENCES catalog_import_messages(message_id,edition_id),FOREIGN KEY(edition_id) REFERENCES "software_documents"(edition_id)) STRICT, WITHOUT ROWID;
CREATE TABLE "software_list_root_import_messages"(message_id INTEGER NOT NULL,edition_id INTEGER NOT NULL,"set_group_id" INTEGER NOT NULL,role TEXT NOT NULL CHECK(role IN ('primary','related')),PRIMARY KEY(message_id,edition_id,role),FOREIGN KEY(message_id,edition_id) REFERENCES catalog_import_messages(message_id,edition_id),FOREIGN KEY(set_group_id) REFERENCES software_lists(set_group_id), FOREIGN KEY(set_group_id,edition_id) REFERENCES catalog_set_groups(set_group_id,edition_id)) STRICT, WITHOUT ROWID;
CREATE TABLE "software_wrapper_import_messages"(message_id INTEGER NOT NULL,edition_id INTEGER NOT NULL,"wrapper_id" INTEGER NOT NULL,role TEXT NOT NULL CHECK(role IN ('primary','related')),PRIMARY KEY(message_id,edition_id,role),FOREIGN KEY(message_id,edition_id) REFERENCES catalog_import_messages(message_id,edition_id),FOREIGN KEY("wrapper_id",edition_id) REFERENCES "software_wrapper_headers"("wrapper_id",edition_id)) STRICT, WITHOUT ROWID;
CREATE TABLE "no_intro_dat_root_import_messages"(message_id INTEGER NOT NULL,edition_id INTEGER NOT NULL,role TEXT NOT NULL CHECK(role IN ('primary','related')),PRIMARY KEY(message_id,edition_id,role),FOREIGN KEY(message_id,edition_id) REFERENCES catalog_import_messages(message_id,edition_id),FOREIGN KEY(edition_id) REFERENCES "no_intro_dat_documents"(edition_id)) STRICT, WITHOUT ROWID;
