CREATE TABLE "no_intro_export_datafile_import_messages"(message_id INTEGER NOT NULL,edition_id INTEGER NOT NULL,role TEXT NOT NULL CHECK(role IN ('primary','related')),PRIMARY KEY(message_id,edition_id,role),FOREIGN KEY(message_id,edition_id) REFERENCES catalog_import_messages(message_id,edition_id),FOREIGN KEY(edition_id) REFERENCES "no_intro_export_datafiles"(edition_id)) STRICT, WITHOUT ROWID;
CREATE TABLE "no_intro_export_header_import_messages"(message_id INTEGER NOT NULL,edition_id INTEGER NOT NULL,"header_id" INTEGER NOT NULL,role TEXT NOT NULL CHECK(role IN ('primary','related')),PRIMARY KEY(message_id,edition_id,role),FOREIGN KEY(message_id,edition_id) REFERENCES catalog_import_messages(message_id,edition_id),FOREIGN KEY("header_id",edition_id) REFERENCES "no_intro_export_headers"("header_id",edition_id)) STRICT, WITHOUT ROWID;
CREATE TABLE "no_intro_pc_root_import_messages"(message_id INTEGER NOT NULL,edition_id INTEGER NOT NULL,role TEXT NOT NULL CHECK(role IN ('primary','related')),PRIMARY KEY(message_id,edition_id,role),FOREIGN KEY(message_id,edition_id) REFERENCES catalog_import_messages(message_id,edition_id),FOREIGN KEY(edition_id) REFERENCES "no_intro_pc_documents"(edition_id)) STRICT, WITHOUT ROWID;
CREATE VIEW candidate_ordinary_message_owners AS SELECT native."source_element_id" AS source_element_id,header.edition_id AS edition_id,
            'no_intro_export_header_field' AS element_kind,NULL AS extent_view,NULL AS extent_start,NULL AS extent_end,
            'transport_decoded_xml_text' AS location_view,native.source_line AS start_line,native.source_column AS start_column,
            native.source_end_line AS end_line,native.source_end_column AS end_column,
            'one_based_unicode_scalar' AS column_convention
            FROM "no_intro_export_header_fields" AS native CROSS JOIN no_intro_export_headers AS header ON header.header_id=native.header_id CROSS JOIN no_intro_export_documents AS document ON document.edition_id=header.edition_id CROSS JOIN catalog_set_groups AS root_group ON root_group.set_group_id=document.root_set_group_id AND root_group.edition_id=header.edition_id AND root_group.group_kind='root' CROSS JOIN catalog_source_elements AS element0 ON element0.source_element_id=native.source_element_id AND element0.element_kind='no_intro_export_header_field' AND element0.edition_id=header.edition_id UNION ALL SELECT native."set_id" AS source_element_id,groups.edition_id AS edition_id,
            'no_intro_export_game' AS element_kind,native.extent_view AS extent_view,native.extent_start AS extent_start,native.extent_end AS extent_end,
            'transport_decoded_xml_text' AS location_view,sets.source_line AS start_line,sets.source_column AS start_column,
            native.source_end_line AS end_line,native.source_end_column AS end_column,
            'one_based_unicode_scalar' AS column_convention
            FROM "no_intro_export_games" AS native CROSS JOIN catalog_sets AS sets ON sets.set_id=native.set_id CROSS JOIN catalog_set_groups AS groups ON groups.set_group_id=sets.set_group_id CROSS JOIN no_intro_export_documents AS document ON document.edition_id=groups.edition_id AND document.root_set_group_id=groups.set_group_id CROSS JOIN catalog_source_elements AS element0 ON element0.source_element_id=native.set_id AND element0.element_kind='no_intro_export_game' AND element0.edition_id=groups.edition_id WHERE groups.group_kind='root' UNION ALL SELECT native."archive_id" AS source_element_id,groups.edition_id AS edition_id,
            'no_intro_export_archive' AS element_kind,NULL AS extent_view,NULL AS extent_start,NULL AS extent_end,
            'transport_decoded_xml_text' AS location_view,native.source_line AS start_line,native.source_column AS start_column,
            native.source_end_line AS end_line,native.source_end_column AS end_column,
            'one_based_unicode_scalar' AS column_convention
            FROM "no_intro_archive_descriptions" AS native CROSS JOIN no_intro_export_games AS game ON game.set_id=native.set_id CROSS JOIN catalog_sets AS sets ON sets.set_id=game.set_id CROSS JOIN catalog_set_groups AS groups ON groups.set_group_id=sets.set_group_id CROSS JOIN no_intro_export_documents AS document ON document.edition_id=groups.edition_id AND document.root_set_group_id=groups.set_group_id CROSS JOIN catalog_source_elements AS element0 ON element0.source_element_id=native.archive_id AND element0.element_kind='no_intro_export_archive' AND element0.edition_id=groups.edition_id CROSS JOIN catalog_source_elements AS element1 ON element1.source_element_id=game.set_id AND element1.element_kind='no_intro_export_game' AND element1.edition_id=groups.edition_id WHERE groups.group_kind='root' UNION ALL SELECT native."dump_source_id" AS source_element_id,groups.edition_id AS edition_id,
            'no_intro_export_dump_source' AS element_kind,NULL AS extent_view,NULL AS extent_start,NULL AS extent_end,
            'transport_decoded_xml_text' AS location_view,native.source_line AS start_line,native.source_column AS start_column,
            native.source_end_line AS end_line,native.source_end_column AS end_column,
            'one_based_unicode_scalar' AS column_convention
            FROM "no_intro_dump_sources" AS native CROSS JOIN no_intro_export_games AS game ON game.set_id=native.set_id CROSS JOIN catalog_sets AS sets ON sets.set_id=game.set_id CROSS JOIN catalog_set_groups AS groups ON groups.set_group_id=sets.set_group_id CROSS JOIN no_intro_export_documents AS document ON document.edition_id=groups.edition_id AND document.root_set_group_id=groups.set_group_id CROSS JOIN catalog_source_elements AS element0 ON element0.source_element_id=native.dump_source_id AND element0.element_kind='no_intro_export_dump_source' AND element0.edition_id=groups.edition_id CROSS JOIN catalog_source_elements AS element1 ON element1.source_element_id=game.set_id AND element1.element_kind='no_intro_export_game' AND element1.edition_id=groups.edition_id WHERE groups.group_kind='root' UNION ALL SELECT native."details_element_id" AS source_element_id,groups.edition_id AS edition_id,
            'no_intro_export_dump_details' AS element_kind,NULL AS extent_view,NULL AS extent_start,NULL AS extent_end,
            'transport_decoded_xml_text' AS location_view,native.source_line AS start_line,native.source_column AS start_column,
            native.source_end_line AS end_line,native.source_end_column AS end_column,
            'one_based_unicode_scalar' AS column_convention
            FROM "no_intro_dump_details" AS native CROSS JOIN no_intro_dump_sources AS parent ON parent.dump_source_id=native.dump_source_id CROSS JOIN no_intro_export_games AS game ON game.set_id=parent.set_id CROSS JOIN catalog_sets AS sets ON sets.set_id=game.set_id CROSS JOIN catalog_set_groups AS groups ON groups.set_group_id=sets.set_group_id CROSS JOIN no_intro_export_documents AS document ON document.edition_id=groups.edition_id AND document.root_set_group_id=groups.set_group_id CROSS JOIN catalog_source_elements AS element0 ON element0.source_element_id=native.details_element_id AND element0.element_kind='no_intro_export_dump_details' AND element0.edition_id=groups.edition_id CROSS JOIN catalog_source_elements AS element1 ON element1.source_element_id=parent.dump_source_id AND element1.element_kind='no_intro_export_dump_source' AND element1.edition_id=groups.edition_id CROSS JOIN catalog_source_elements AS element2 ON element2.source_element_id=game.set_id AND element2.element_kind='no_intro_export_game' AND element2.edition_id=groups.edition_id WHERE groups.group_kind='root' UNION ALL SELECT native."serials_element_id" AS source_element_id,groups.edition_id AS edition_id,
            'no_intro_export_dump_serials' AS element_kind,NULL AS extent_view,NULL AS extent_start,NULL AS extent_end,
