            'no_intro_export_source_file' AS element_kind,NULL AS extent_view,NULL AS extent_start,NULL AS extent_end,
            'transport_decoded_xml_text' AS location_view,native.source_line AS start_line,native.source_column AS start_column,
            native.source_end_line AS end_line,native.source_end_column AS end_column,
            'one_based_unicode_scalar' AS column_convention
            FROM "no_intro_dump_files" AS native CROSS JOIN no_intro_dump_sources AS parent ON parent.dump_source_id=native.dump_source_id CROSS JOIN no_intro_export_games AS game ON game.set_id=parent.set_id CROSS JOIN catalog_sets AS sets ON sets.set_id=game.set_id CROSS JOIN catalog_set_groups AS groups ON groups.set_group_id=sets.set_group_id CROSS JOIN no_intro_export_documents AS document ON document.edition_id=groups.edition_id AND document.root_set_group_id=groups.set_group_id CROSS JOIN catalog_source_elements AS element0 ON element0.source_element_id=native.media_entry_id AND element0.element_kind='no_intro_export_source_file' AND element0.edition_id=groups.edition_id CROSS JOIN catalog_source_elements AS element1 ON element1.source_element_id=parent.dump_source_id AND element1.element_kind='no_intro_export_dump_source' AND element1.edition_id=groups.edition_id CROSS JOIN catalog_source_elements AS element2 ON element2.source_element_id=game.set_id AND element2.element_kind='no_intro_export_game' AND element2.edition_id=groups.edition_id CROSS JOIN catalog_media_entries AS media ON media.media_entry_id=native.media_entry_id WHERE groups.group_kind='root' UNION ALL SELECT native."release_id" AS source_element_id,groups.edition_id AS edition_id,
            'no_intro_export_release' AS element_kind,NULL AS extent_view,NULL AS extent_start,NULL AS extent_end,
            'transport_decoded_xml_text' AS location_view,native.source_line AS start_line,native.source_column AS start_column,
            native.source_end_line AS end_line,native.source_end_column AS end_column,
            'one_based_unicode_scalar' AS column_convention
            FROM "no_intro_releases" AS native CROSS JOIN no_intro_export_games AS game ON game.set_id=native.set_id CROSS JOIN catalog_sets AS sets ON sets.set_id=game.set_id CROSS JOIN catalog_set_groups AS groups ON groups.set_group_id=sets.set_group_id CROSS JOIN no_intro_export_documents AS document ON document.edition_id=groups.edition_id AND document.root_set_group_id=groups.set_group_id CROSS JOIN catalog_source_elements AS element0 ON element0.source_element_id=native.release_id AND element0.element_kind='no_intro_export_release' AND element0.edition_id=groups.edition_id CROSS JOIN catalog_source_elements AS element1 ON element1.source_element_id=game.set_id AND element1.element_kind='no_intro_export_game' AND element1.edition_id=groups.edition_id WHERE groups.group_kind='root' UNION ALL SELECT native."details_element_id" AS source_element_id,groups.edition_id AS edition_id,
            'no_intro_export_release_details' AS element_kind,NULL AS extent_view,NULL AS extent_start,NULL AS extent_end,
            'transport_decoded_xml_text' AS location_view,native.source_line AS start_line,native.source_column AS start_column,
            native.source_end_line AS end_line,native.source_end_column AS end_column,
            'one_based_unicode_scalar' AS column_convention
            FROM "no_intro_release_details" AS native CROSS JOIN no_intro_releases AS parent ON parent.release_id=native.release_id CROSS JOIN no_intro_export_games AS game ON game.set_id=parent.set_id CROSS JOIN catalog_sets AS sets ON sets.set_id=game.set_id CROSS JOIN catalog_set_groups AS groups ON groups.set_group_id=sets.set_group_id CROSS JOIN no_intro_export_documents AS document ON document.edition_id=groups.edition_id AND document.root_set_group_id=groups.set_group_id CROSS JOIN catalog_source_elements AS element0 ON element0.source_element_id=native.details_element_id AND element0.element_kind='no_intro_export_release_details' AND element0.edition_id=groups.edition_id CROSS JOIN catalog_source_elements AS element1 ON element1.source_element_id=parent.release_id AND element1.element_kind='no_intro_export_release' AND element1.edition_id=groups.edition_id CROSS JOIN catalog_source_elements AS element2 ON element2.source_element_id=game.set_id AND element2.element_kind='no_intro_export_game' AND element2.edition_id=groups.edition_id WHERE groups.group_kind='root' UNION ALL SELECT native."serials_element_id" AS source_element_id,groups.edition_id AS edition_id,
            'no_intro_export_release_serials' AS element_kind,NULL AS extent_view,NULL AS extent_start,NULL AS extent_end,
            'transport_decoded_xml_text' AS location_view,native.source_line AS start_line,native.source_column AS start_column,
            native.source_end_line AS end_line,native.source_end_column AS end_column,
            'one_based_unicode_scalar' AS column_convention
            FROM "no_intro_release_serials" AS native CROSS JOIN no_intro_releases AS parent ON parent.release_id=native.release_id CROSS JOIN no_intro_export_games AS game ON game.set_id=parent.set_id CROSS JOIN catalog_sets AS sets ON sets.set_id=game.set_id CROSS JOIN catalog_set_groups AS groups ON groups.set_group_id=sets.set_group_id CROSS JOIN no_intro_export_documents AS document ON document.edition_id=groups.edition_id AND document.root_set_group_id=groups.set_group_id CROSS JOIN catalog_source_elements AS element0 ON element0.source_element_id=native.serials_element_id AND element0.element_kind='no_intro_export_release_serials' AND element0.edition_id=groups.edition_id CROSS JOIN catalog_source_elements AS element1 ON element1.source_element_id=parent.release_id AND element1.element_kind='no_intro_export_release' AND element1.edition_id=groups.edition_id CROSS JOIN catalog_source_elements AS element2 ON element2.source_element_id=game.set_id AND element2.element_kind='no_intro_export_game' AND element2.edition_id=groups.edition_id WHERE groups.group_kind='root' UNION ALL SELECT native."media_entry_id" AS source_element_id,groups.edition_id AS edition_id,
            'no_intro_export_release_file' AS element_kind,NULL AS extent_view,NULL AS extent_start,NULL AS extent_end,
            'transport_decoded_xml_text' AS location_view,native.source_line AS start_line,native.source_column AS start_column,
            native.source_end_line AS end_line,native.source_end_column AS end_column,
            'one_based_unicode_scalar' AS column_convention
            FROM "no_intro_release_files" AS native CROSS JOIN no_intro_releases AS parent ON parent.release_id=native.release_id CROSS JOIN no_intro_export_games AS game ON game.set_id=parent.set_id CROSS JOIN catalog_sets AS sets ON sets.set_id=game.set_id CROSS JOIN catalog_set_groups AS groups ON groups.set_group_id=sets.set_group_id CROSS JOIN no_intro_export_documents AS document ON document.edition_id=groups.edition_id AND document.root_set_group_id=groups.set_group_id CROSS JOIN catalog_source_elements AS element0 ON element0.source_element_id=native.media_entry_id AND element0.element_kind='no_intro_export_release_file' AND element0.edition_id=groups.edition_id CROSS JOIN catalog_source_elements AS element1 ON element1.source_element_id=parent.release_id AND element1.element_kind='no_intro_export_release' AND element1.edition_id=groups.edition_id CROSS JOIN catalog_source_elements AS element2 ON element2.source_element_id=game.set_id AND element2.element_kind='no_intro_export_game' AND element2.edition_id=groups.edition_id CROSS JOIN catalog_media_entries AS media ON media.media_entry_id=native.media_entry_id WHERE groups.group_kind='root';
CREATE VIEW candidate_ordinary_message_problems AS
        SELECT 'ordinary_message_owner' AS problem,link.message_id AS owner_id,link.edition_id
        FROM catalog_import_message_elements AS link WHERE NOT EXISTS(SELECT 1 FROM catalog_import_messages AS message
        JOIN catalog_imports AS run ON run.import_id=message.import_id
        JOIN catalog_editions AS edition ON edition.edition_id=run.edition_id
            AND edition.catalog_id=run.catalog_id AND edition.source_file_id=run.source_file_id
            AND edition.reading_rules_id=run.reading_rules_id
        JOIN catalog_reading_rules AS rules ON rules.reading_rules_id=edition.reading_rules_id
            AND rules.format_family='no_intro_database'
        JOIN catalog_source_files AS source ON source.source_file_id=edition.source_file_id
        LEFT JOIN catalog_decoded_xml_views AS decoded ON decoded.source_file_id=source.source_file_id
        JOIN candidate_ordinary_message_owners AS owner ON owner.source_element_id=link.source_element_id
            AND owner.edition_id=link.edition_id
        WHERE message.message_id=link.message_id AND message.edition_id=link.edition_id
            AND run.edition_id=link.edition_id AND message.source_file_id=run.source_file_id
            AND message.reading_rules_id=run.reading_rules_id AND run.status<>'failed'
            AND (((owner.extent_view IS NOT NULL AND (CASE WHEN message.source_view=owner.extent_view AND message.source_problem_start IS NOT NULL THEN message.source_problem_start WHEN owner.extent_view='retained_original_bytes' THEN message.original_problem_start END) IS NOT NULL)) IS TRUE OR ((message.line IS NOT NULL AND message.column IS NOT NULL AND owner.start_line IS NOT NULL AND owner.start_column IS NOT NULL AND owner.end_line IS NOT NULL AND owner.end_column IS NOT NULL AND message.location_view=owner.location_view AND message.column_convention=owner.column_convention)) IS TRUE) AND (((owner.extent_view IS NOT NULL AND (CASE WHEN message.source_view=owner.extent_view AND message.source_problem_start IS NOT NULL THEN message.source_problem_start WHEN owner.extent_view='retained_original_bytes' THEN message.original_problem_start END) IS NOT NULL)) IS NOT TRUE OR ((owner.extent_start>=0 AND owner.extent_start<owner.extent_end AND owner.extent_end<=(CASE owner.extent_view WHEN 'retained_original_bytes' THEN source.byte_length WHEN 'transport_decoded_xml_bytes' THEN decoded.byte_length END) AND owner.extent_start<=(CASE WHEN message.source_view=owner.extent_view AND message.source_problem_start IS NOT NULL THEN message.source_problem_start WHEN owner.extent_view='retained_original_bytes' THEN message.original_problem_start END) AND (CASE WHEN message.source_view=owner.extent_view AND message.source_problem_start IS NOT NULL THEN message.source_problem_start WHEN owner.extent_view='retained_original_bytes' THEN message.original_problem_start END)<owner.extent_end AND (CASE WHEN message.source_view=owner.extent_view AND message.source_problem_start IS NOT NULL THEN message.source_problem_start WHEN owner.extent_view='retained_original_bytes' THEN message.original_problem_start END)<=(CASE WHEN message.source_view=owner.extent_view AND message.source_problem_end IS NOT NULL THEN message.source_problem_end WHEN owner.extent_view='retained_original_bytes' THEN message.original_problem_end END) AND (CASE WHEN message.source_view=owner.extent_view AND message.source_problem_end IS NOT NULL THEN message.source_problem_end WHEN owner.extent_view='retained_original_bytes' THEN message.original_problem_end END)<=owner.extent_end)) IS TRUE) AND (((message.line IS NOT NULL AND message.column IS NOT NULL AND owner.start_line IS NOT NULL AND owner.start_column IS NOT NULL AND owner.end_line IS NOT NULL AND owner.end_column IS NOT NULL AND message.location_view=owner.location_view AND message.column_convention=owner.column_convention)) IS NOT TRUE OR (((owner.start_line,owner.start_column)<(owner.end_line,owner.end_column) AND (message.line,message.column)>=(owner.start_line,owner.start_column) AND (message.line,message.column)<(owner.end_line,owner.end_column))) IS TRUE));
CREATE VIEW candidate_ordinary_owner_interval_problems AS SELECT 'ordinary_owner_interval:no_intro_export_header_fields' AS problem,
            native."source_element_id" AS owner_id,element.edition_id
