CREATE VIEW candidate_relationship_positions AS SELECT position.relationship_id,CASE position.field_kind WHEN 'cloneof' THEN 'mame_cloneof' WHEN 'romof' THEN 'mame_romof' WHEN 'sampleof' THEN 'mame_sampleof' END AS reported_kind,position."set_id" AS source_element_id,position.field_occurrence,element.edition_id FROM "mame_machines_attribute_positions" AS position LEFT JOIN catalog_source_elements AS element ON element.source_element_id=position."set_id" WHERE position.relationship_id IS NOT NULL UNION ALL SELECT position.relationship_id,CASE position.field_kind WHEN 'name' THEN 'mame_device_ref' END AS reported_kind,position."source_element_id" AS source_element_id,position.field_occurrence,element.edition_id FROM "mame_device_references_attribute_positions" AS position LEFT JOIN catalog_source_elements AS element ON element.source_element_id=position."source_element_id" WHERE position.relationship_id IS NOT NULL UNION ALL SELECT position.relationship_id,CASE position.field_kind WHEN 'merge' THEN 'mame_rom_merge' END AS reported_kind,position."media_entry_id" AS source_element_id,position.field_occurrence,element.edition_id FROM "mame_rom_claims_attribute_positions" AS position LEFT JOIN catalog_source_elements AS element ON element.source_element_id=position."media_entry_id" WHERE position.relationship_id IS NOT NULL UNION ALL SELECT position.relationship_id,CASE position.field_kind WHEN 'merge' THEN 'mame_disk_merge' END AS reported_kind,position."media_entry_id" AS source_element_id,position.field_occurrence,element.edition_id FROM "mame_disk_claims_attribute_positions" AS position LEFT JOIN catalog_source_elements AS element ON element.source_element_id=position."media_entry_id" WHERE position.relationship_id IS NOT NULL UNION ALL SELECT position.relationship_id,CASE position.field_kind WHEN 3 THEN 'logiqx_cloneof' WHEN 4 THEN 'logiqx_romof' WHEN 5 THEN 'logiqx_sampleof' END AS reported_kind,position."set_id" AS source_element_id,position.field_occurrence,element.edition_id FROM "logiqx_game_attribute_positions" AS position LEFT JOIN catalog_source_elements AS element ON element.source_element_id=position."set_id" WHERE position.relationship_id IS NOT NULL UNION ALL SELECT position.relationship_id,CASE position.field_kind WHEN 0 THEN 'logiqx_device_ref' END AS reported_kind,position."source_element_id" AS source_element_id,position.field_occurrence,element.edition_id FROM "logiqx_device_reference_attribute_positions" AS position LEFT JOIN catalog_source_elements AS element ON element.source_element_id=position."source_element_id" WHERE position.relationship_id IS NOT NULL UNION ALL SELECT position.relationship_id,CASE position.field_kind WHEN 5 THEN 'logiqx_rom_merge' END AS reported_kind,position."media_entry_id" AS source_element_id,position.field_occurrence,element.edition_id FROM "logiqx_rom_attribute_positions" AS position LEFT JOIN catalog_source_elements AS element ON element.source_element_id=position."media_entry_id" WHERE position.relationship_id IS NOT NULL UNION ALL SELECT position.relationship_id,CASE position.field_kind WHEN 3 THEN 'logiqx_disk_merge' END AS reported_kind,position."media_entry_id" AS source_element_id,position.field_occurrence,element.edition_id FROM "logiqx_disk_attribute_positions" AS position LEFT JOIN catalog_source_elements AS element ON element.source_element_id=position."media_entry_id" WHERE position.relationship_id IS NOT NULL UNION ALL SELECT position.relationship_id,CASE position.field_kind WHEN 1 THEN 'clrmamepro_cloneof' WHEN 6 THEN 'clrmamepro_sampleof' END AS reported_kind,position."set_id" AS source_element_id,position.field_occurrence,element.edition_id FROM "clrmamepro_set_field_positions" AS position LEFT JOIN catalog_source_elements AS element ON element.source_element_id=position."set_id" WHERE position.relationship_id IS NOT NULL UNION ALL SELECT position.relationship_id,CASE position.field_kind WHEN 6 THEN 'clrmamepro_rom_merge' END AS reported_kind,position."media_entry_id" AS source_element_id,position.field_occurrence,element.edition_id FROM "clrmamepro_rom_field_positions" AS position LEFT JOIN catalog_source_elements AS element ON element.source_element_id=position."media_entry_id" WHERE position.relationship_id IS NOT NULL UNION ALL SELECT position.relationship_id,CASE position.field_kind WHEN 1 THEN 'software_cloneof' END AS reported_kind,position."set_id" AS source_element_id,position.field_occurrence,element.edition_id FROM "software_title_attribute_positions" AS position LEFT JOIN catalog_source_elements AS element ON element.source_element_id=position."set_id" WHERE position.relationship_id IS NOT NULL UNION ALL SELECT position.relationship_id,CASE position.field_kind WHEN 'cloneof' THEN 'no_intro_dat_cloneof' WHEN 'cloneofid' THEN 'no_intro_dat_cloneofid' END AS reported_kind,position."set_id" AS source_element_id,position.field_occurrence,element.edition_id FROM "no_intro_dat_game_field_positions" AS position LEFT JOIN catalog_source_elements AS element ON element.source_element_id=position."set_id" WHERE position.relationship_id IS NOT NULL UNION ALL SELECT position.relationship_id,CASE position.field_kind WHEN 'clone' THEN 'no_intro_database_archive_clone' WHEN 'mergeof' THEN 'no_intro_database_archive_mergeof' END AS reported_kind,position."archive_id" AS source_element_id,position.field_occurrence,element.edition_id FROM "no_intro_archive_field_positions" AS position LEFT JOIN catalog_source_elements AS element ON element.source_element_id=position."archive_id" WHERE position.relationship_id IS NOT NULL UNION ALL SELECT position.relationship_id,CASE position.field_kind WHEN 'clone' THEN 'no_intro_pc_clone' WHEN 'mergeof' THEN 'no_intro_pc_mergeof' END AS reported_kind,position."source_element_id" AS source_element_id,position.field_occurrence,element.edition_id FROM "no_intro_pc_game_attribute_positions" AS position LEFT JOIN catalog_source_elements AS element ON element.source_element_id=position."source_element_id" WHERE position.relationship_id IS NOT NULL;

CREATE VIEW candidate_relationship_closure_problems AS SELECT 'sealed_relationship_payload_or_endpoint' AS problem,relationship.relationship_id AS owner_id,relationship.edition_id FROM catalog_relationships AS relationship WHERE relationship.origin IN ('user','derived') AND (EXISTS(SELECT 1 FROM catalog_relationship_evidence_publications AS evidence WHERE evidence.relationship_id=relationship.relationship_id) OR EXISTS(SELECT 1 FROM catalog_relationship_reviews AS review JOIN catalog_relationship_review_publications AS publication USING(review_id) WHERE review.relationship_id=relationship.relationship_id AND review.decision='accepted')) AND (NOT ((relationship.origin='user' AND EXISTS(SELECT 1 FROM manual_catalog_relationships AS payload WHERE payload.relationship_id=relationship.relationship_id) AND NOT EXISTS(SELECT 1 FROM inferred_catalog_relationships AS payload WHERE payload.relationship_id=relationship.relationship_id) AND NOT EXISTS(SELECT 1 FROM reported_catalog_relationships AS payload WHERE payload.relationship_id=relationship.relationship_id)) OR (relationship.origin='derived' AND EXISTS(SELECT 1 FROM inferred_catalog_relationships AS payload WHERE payload.relationship_id=relationship.relationship_id) AND NOT EXISTS(SELECT 1 FROM manual_catalog_relationships AS payload WHERE payload.relationship_id=relationship.relationship_id) AND NOT EXISTS(SELECT 1 FROM reported_catalog_relationships AS payload WHERE payload.relationship_id=relationship.relationship_id))) OR (relationship.origin='user' AND EXISTS(SELECT 1 FROM manual_catalog_relationships AS payload WHERE payload.relationship_id=relationship.relationship_id AND NOT EXISTS(SELECT 1 FROM catalog_relationship_targets AS target WHERE target.target_id=payload.from_target_id AND ((SELECT count(*) FROM catalog_set_targets AS subtype WHERE subtype.target_id=payload.from_target_id) + (SELECT count(*) FROM catalog_media_entry_targets AS subtype WHERE subtype.target_id=payload.from_target_id) + (SELECT count(*) FROM no_intro_archive_targets AS subtype WHERE subtype.target_id=payload.from_target_id) + (SELECT count(*) FROM shared_file_targets AS subtype WHERE subtype.target_id=payload.from_target_id) + (SELECT count(*) FROM declared_hash_targets AS subtype WHERE subtype.target_id=payload.from_target_id) + (SELECT count(*) FROM observed_content_hash_targets AS subtype WHERE subtype.target_id=payload.from_target_id) + (SELECT count(*) FROM unresolved_catalog_targets AS subtype WHERE subtype.target_id=payload.from_target_id) + (SELECT count(*) FROM external_catalog_targets AS subtype WHERE subtype.target_id=payload.from_target_id))=1 AND (target.target_kind='catalog_set' AND EXISTS(SELECT 1 FROM catalog_set_targets AS typed JOIN catalog_sets AS owner ON owner.set_id=typed.set_id JOIN catalog_set_groups AS groups ON groups.set_group_id=owner.set_group_id JOIN catalog_source_elements AS element ON element.source_element_id=owner.set_id JOIN candidate_native_owners AS native ON native.source_element_id=owner.set_id AND native.element_kind=element.element_kind JOIN published_catalog_editions AS publication ON publication.edition_id=groups.edition_id WHERE typed.target_id=payload.from_target_id AND element.edition_id=groups.edition_id AND native.element_kind IN ('clrmamepro_set','logiqx_game','mame_machine','no_intro_dat_game','no_intro_export_game','no_intro_pc_game','software_item') AND (SELECT count(*) FROM candidate_native_owners AS actual WHERE actual.source_element_id=owner.set_id AND actual.element_kind<>'common_set_placement')=1) OR target.target_kind='catalog_media_entry' AND EXISTS(SELECT 1 FROM catalog_media_entry_targets AS typed JOIN catalog_media_entries AS owner ON owner.media_entry_id=typed.media_entry_id JOIN catalog_source_elements AS element ON element.source_element_id=owner.media_entry_id JOIN candidate_native_owners AS native ON native.source_element_id=owner.media_entry_id AND native.element_kind=element.element_kind JOIN published_catalog_editions AS publication ON publication.edition_id=element.edition_id WHERE typed.target_id=payload.from_target_id AND native.element_kind IN ('clrmamepro_rom','clrmamepro_sample','logiqx_disk','logiqx_rom','logiqx_sample','mame_disk','mame_rom','mame_sample','no_intro_dat_rom','no_intro_export_release_file','no_intro_export_source_file','no_intro_pc_rom','software_disk_entry','software_rom_entry') AND (SELECT count(*) FROM candidate_native_owners AS actual WHERE actual.source_element_id=owner.media_entry_id)=1) OR target.target_kind='no_intro_archive' AND EXISTS(SELECT 1 FROM no_intro_archive_targets AS typed JOIN no_intro_archive_descriptions AS archive ON archive.archive_id=typed.archive_id JOIN catalog_source_elements AS element ON element.source_element_id=archive.archive_id AND element.element_kind='no_intro_export_archive' JOIN no_intro_export_games AS game ON game.set_id=archive.set_id JOIN catalog_source_elements AS game_element ON game_element.source_element_id=game.set_id AND game_element.element_kind='no_intro_export_game' JOIN catalog_sets AS sets ON sets.set_id=game.set_id JOIN catalog_set_groups AS groups ON groups.set_group_id=sets.set_group_id AND groups.group_kind='root' JOIN catalog_editions AS edition ON edition.edition_id=groups.edition_id JOIN no_intro_export_documents AS document ON document.edition_id=edition.edition_id AND document.root_set_group_id=groups.set_group_id JOIN catalog_reading_rules AS rules ON rules.reading_rules_id=edition.reading_rules_id AND rules.format_family='no_intro_database' JOIN published_catalog_editions AS publication ON publication.edition_id=edition.edition_id AND publication.catalog_id=edition.catalog_id AND publication.source_file_id=edition.source_file_id AND publication.reading_rules_id=edition.reading_rules_id AND publication.coverage_id=edition.coverage_id WHERE typed.target_id=payload.from_target_id AND element.edition_id=edition.edition_id AND game_element.edition_id=edition.edition_id AND ((SELECT count(*) FROM "mame_machines