CREATE VIEW candidate_physical_extent_problems AS SELECT 'physical_extent:clrmamepro_documents' AS problem,
            owner."edition_id" AS owner_id,owner.edition_id AS edition_id
            FROM "clrmamepro_documents" AS owner WHERE (owner.extent_view IS NOT NULL OR owner.extent_start IS NOT NULL OR owner.extent_end IS NOT NULL) AND NOT EXISTS(SELECT 1 FROM catalog_editions AS edition
            JOIN catalog_source_files AS source ON source.source_file_id=edition.source_file_id
            LEFT JOIN catalog_decoded_xml_views AS decoded ON decoded.source_file_id=source.source_file_id
            WHERE edition.edition_id=owner.edition_id AND owner.extent_start>=0
                AND owner.extent_start<owner.extent_end
                AND owner.extent_end<=CASE owner.extent_view
                    WHEN 'retained_original_bytes' THEN source.byte_length
                    WHEN 'transport_decoded_xml_bytes' THEN decoded.byte_length END) UNION ALL SELECT 'physical_extent:logiqx_documents' AS problem,
            owner."edition_id" AS owner_id,owner.edition_id AS edition_id
            FROM "logiqx_documents" AS owner WHERE (owner.extent_view IS NOT NULL OR owner.extent_start IS NOT NULL OR owner.extent_end IS NOT NULL) AND NOT EXISTS(SELECT 1 FROM catalog_editions AS edition
            JOIN catalog_source_files AS source ON source.source_file_id=edition.source_file_id
            LEFT JOIN catalog_decoded_xml_views AS decoded ON decoded.source_file_id=source.source_file_id
            WHERE edition.edition_id=owner.edition_id AND owner.extent_start>=0
                AND owner.extent_start<owner.extent_end
                AND owner.extent_end<=CASE owner.extent_view
                    WHEN 'retained_original_bytes' THEN source.byte_length
                    WHEN 'transport_decoded_xml_bytes' THEN decoded.byte_length END) UNION ALL SELECT 'physical_extent:mame_documents' AS problem,
            owner."edition_id" AS owner_id,owner.edition_id AS edition_id
            FROM "mame_documents" AS owner WHERE (owner.extent_view IS NOT NULL OR owner.extent_start IS NOT NULL OR owner.extent_end IS NOT NULL) AND NOT EXISTS(SELECT 1 FROM catalog_editions AS edition
            JOIN catalog_source_files AS source ON source.source_file_id=edition.source_file_id
            LEFT JOIN catalog_decoded_xml_views AS decoded ON decoded.source_file_id=source.source_file_id
            WHERE edition.edition_id=owner.edition_id AND owner.extent_start>=0
                AND owner.extent_start<owner.extent_end
                AND owner.extent_end<=CASE owner.extent_view
                    WHEN 'retained_original_bytes' THEN source.byte_length
                    WHEN 'transport_decoded_xml_bytes' THEN decoded.byte_length END) UNION ALL SELECT 'physical_extent:no_intro_dat_documents' AS problem,
            owner."edition_id" AS owner_id,owner.edition_id AS edition_id
            FROM "no_intro_dat_documents" AS owner WHERE (owner.extent_view IS NOT NULL OR owner.extent_start IS NOT NULL OR owner.extent_end IS NOT NULL) AND NOT EXISTS(SELECT 1 FROM catalog_editions AS edition
            JOIN catalog_source_files AS source ON source.source_file_id=edition.source_file_id
            LEFT JOIN catalog_decoded_xml_views AS decoded ON decoded.source_file_id=source.source_file_id
            WHERE edition.edition_id=owner.edition_id AND owner.extent_start>=0
                AND owner.extent_start<owner.extent_end
                AND owner.extent_end<=CASE owner.extent_view
                    WHEN 'retained_original_bytes' THEN source.byte_length
                    WHEN 'transport_decoded_xml_bytes' THEN decoded.byte_length END) UNION ALL SELECT 'physical_extent:no_intro_export_datafiles' AS problem,
            owner."edition_id" AS owner_id,owner.edition_id AS edition_id
            FROM "no_intro_export_datafiles" AS owner WHERE (owner.extent_view IS NOT NULL OR owner.extent_start IS NOT NULL OR owner.extent_end IS NOT NULL) AND NOT EXISTS(SELECT 1 FROM catalog_editions AS edition
            JOIN catalog_source_files AS source ON source.source_file_id=edition.source_file_id
            LEFT JOIN catalog_decoded_xml_views AS decoded ON decoded.source_file_id=source.source_file_id
            WHERE edition.edition_id=owner.edition_id AND owner.extent_start>=0
                AND owner.extent_start<owner.extent_end
                AND owner.extent_end<=CASE owner.extent_view
                    WHEN 'retained_original_bytes' THEN source.byte_length
                    WHEN 'transport_decoded_xml_bytes' THEN decoded.byte_length END) UNION ALL SELECT 'physical_extent:no_intro_export_documents' AS problem,
            owner."edition_id" AS owner_id,owner.edition_id AS edition_id
            FROM "no_intro_export_documents" AS owner WHERE (owner.extent_view IS NOT NULL OR owner.extent_start IS NOT NULL OR owner.extent_end IS NOT NULL) AND NOT EXISTS(SELECT 1 FROM catalog_editions AS edition
            JOIN catalog_source_files AS source ON source.source_file_id=edition.source_file_id
            LEFT JOIN catalog_decoded_xml_views AS decoded ON decoded.source_file_id=source.source_file_id
            WHERE edition.edition_id=owner.edition_id AND owner.extent_start>=0
                AND owner.extent_start<owner.extent_end
                AND owner.extent_end<=CASE owner.extent_view
