onship_positions AS position ON position.relationship_id=declaration.relationship_id AND position.reported_kind=declaration.reported_kind AND position.source_element_id=declaration.source_element_id AND position.field_occurrence=0 GROUP BY declaration.relationship_id,declaration.reported_kind,declaration.source_element_id HAVING count(position.relationship_id)<>1 UNION ALL SELECT 'relationship_position_identity',position.relationship_id,coalesce(position.edition_id,identity.edition_id) FROM candidate_relationship_positions AS position LEFT JOIN catalog_relationships AS identity USING(relationship_id) WHERE NOT EXISTS(SELECT 1 FROM candidate_relationship_declarations AS declaration JOIN reported_catalog_relationships AS reported USING(relationship_id,reported_kind) WHERE declaration.relationship_id=position.relationship_id AND declaration.source_element_id=position.source_element_id AND declaration.reported_kind=position.reported_kind AND declaration.edition_id=position.edition_id AND identity.origin='source' AND identity.edition_id=position.edition_id AND position.field_occurrence=0) UNION ALL SELECT 'relationship_marker:no_intro_database_archive_clone',marker."archive_id",element.edition_id FROM "no_intro_archive_clone_markers" AS marker LEFT JOIN catalog_source_elements AS element ON element.source_element_id=marker."archive_id" WHERE EXISTS(SELECT 1 FROM "no_intro_archive_clone_links" WHERE "archive_id"=marker."archive_id") OR (SELECT count(*) FROM "no_intro_archive_field_positions" WHERE "archive_id"=marker."archive_id" AND field_kind='clone' AND field_occurrence=0 AND relationship_id IS NULL)<>1 UNION ALL SELECT 'relationship_missing_marker:no_intro_database_archive_clone',position."archive_id",element.edition_id FROM "no_intro_archive_field_positions" AS position LEFT JOIN catalog_source_elements AS element ON element.source_element_id=position."archive_id" WHERE position.field_kind='clone' AND position.relationship_id IS NULL AND NOT EXISTS(SELECT 1 FROM "no_