CREATE TRIGGER "candidate_native_mame_machines_insert" BEFORE INSERT ON "mame_machines" WHEN NOT EXISTS(SELECT 1 FROM catalog_source_elements AS element JOIN "catalog_sets" AS parent ON parent."set_id"=NEW."set_id" JOIN catalog_editions AS edition ON edition.edition_id=element.edition_id JOIN catalog_reading_rules AS rules USING(reading_rules_id) WHERE element.source_element_id=NEW."set_id" AND element.element_kind='mame_machine' AND element.edition_id=(SELECT edition_id FROM catalog_set_groups WHERE set_group_id=parent.set_group_id) AND rules.format_family='mame') BEGIN SELECT RAISE(ABORT,'candidate native kind or ancestry'); END;

