CREATE TRIGGER "candidate_root_link_mame_root_import_messages_insert" BEFORE INSERT ON "mame_root_import_messages" WHEN NOT EXISTS(SELECT 1 FROM (SELECT NEW."message_id" AS "message_id",NEW."edition_id" AS "edition_id",NEW."role" AS "role") AS link JOIN catalog_import_messages AS message ON message.message_id=link.message_id AND message.edition_id=link.edition_id JOIN catalog_imports AS run ON run.import_id=message.import_id AND run.edition_id=link.edition_id JOIN catalog_editions AS edition ON edition.edition_id=link.edition_id AND edition.catalog_id=run.catalog_id AND edition.source_file_id=message.source_file_id AND edition.reading_rules_id=message.reading_rules_id JOIN catalog_reading_rules AS rules ON rules.reading_rules_id=edition.reading_rules_id AND rules.format_family='mame' JOIN catalog_source_files AS source ON source.source_file_id=edition.source_file_id LEFT JOIN catalog_decoded_xml_views AS decoded ON decoded.source_file_id=source.source_file_id JOIN "mame_documents" AS owner ON owner.edition_id=link.edition_id WHERE link.message_id=NEW.message_id AND link.edition_id=NEW.edition_id AND link.role=NEW.role  AND (((owner.extent_view IS NOT NULL AND (CASE WHEN message.source_view=owner.extent_view AND message.source_problem_start IS NOT NULL THEN message.source_problem_start WHEN owner.extent_view='retained_original_bytes' THEN message.original_problem_start END) IS NOT NULL)) IS TRUE OR ((message.line IS NOT NULL AND message.column IS NOT NULL AND owner.start_line IS NOT NULL AND owner.start_column IS NOT NULL AND owner.end_line IS NOT NULL AND owner.end_column IS NOT NULL AND message.location_view=owner.location_view AND message.column_convention=owner.column_convention)) IS TRUE) AND (((owner.extent_view IS NOT NULL AND (CASE WHEN message.source_view=owner.extent_view AND message.source_problem_start IS NOT NULL THEN message.source_problem_start WHEN owner.extent_view='retained_original_bytes' THEN message.original_problem_start END) IS NOT NULL)) IS NOT TRUE OR ((owner.extent_start>=0 AND owner.extent_start<owner.extent_end AND owner.extent_end<=(CASE owner.extent_view WHEN 'retained_original_bytes' THEN source.byte_length WHEN 'transport_decoded_xml_bytes' THEN decoded.byte_length END) AND owner.extent_start<=(CASE WHEN message.source_view=owner.extent_view AND message.source_problem_start IS NOT NULL THEN message.source_problem_start WHEN owner.extent_view='retained_original_bytes' THEN message.original_problem_start END) AND (CASE WHEN message.source_view=owner.extent_view AND message.source_problem_start IS NOT NULL THEN message.source_problem_start WHEN owner.extent_view='retained_original_bytes' THEN message.original_problem_start END)<owner.extent_end AND (CASE WHEN message.source_view=owner.extent_view AND message.source_problem_start IS NOT NULL THEN message.source_problem_start WHEN owner.extent_view='retained_original_bytes' THEN message.original_problem_start END)<=(CASE WHEN message.source_view=owner.extent_view AND message.source_problem_end IS NOT NULL THEN message.source_problem_end WHEN owner.extent_view='retained_original_bytes' THEN message.original_problem_end END) AND (CASE WHEN message.source_view=owner.extent_view AND message.source_problem_end IS NOT NULL THEN message.source_problem_end WHEN owner.extent_view='retained_original_bytes' THEN message.original_problem_end END)<=owner.extent_end)) IS TRUE) AND (((message.line IS NOT NULL AND message.column IS NOT NULL AND owner.start_line IS NOT NULL AND owner.start_column IS NOT NULL AND owner.end_line IS NOT NULL AND owner.end_column IS NOT NULL AND message.location_view=owner.location_view AND message.column_convention=owner.column_convention)) IS NOT TRUE OR (((owner.start_line,owner.start_column)<(owner.end_line,owner.end_column) AND (message.line,message.column)>=(owner.start_line,owner.start_column) AND (message.line,message.column)<(owner.end_line,owner.end_column))) IS TRUE)) BEGIN SELECT RAISE(ABORT,'root diagnostic requires matching ancestry, mode and proven containment'); END;

