CREATE TRIGGER candidate_terminal_diagnostic_catalog_import_messages_insert
                BEFORE INSERT ON "catalog_import_messages"
                WHEN EXISTS(SELECT 1 FROM catalog_imports AS run WHERE run.import_id=NEW.import_id AND run.status IN ('succeeded','failed'))
