CREATE TRIGGER candidate_terminal_diagnostic_catalog_import_messages_update
                BEFORE UPDATE ON "catalog_import_messages"
                WHEN EXISTS(SELECT 1 FROM catalog_imports AS run WHERE run.import_id=OLD.import_id AND run.status IN ('succeeded','failed')) OR EXISTS(SELECT 1 FROM catalog_imports AS run WHERE run.import_id=NEW.import_id AND run.status IN ('succeeded','failed'))
                BEGIN SELECT RAISE(ABORT,'terminal import diagnostics are immutable'); END;

