CREATE TRIGGER relationship_closure_evidence_guard BEFORE INSERT ON catalog_relationship_evidence_publications WHEN EXISTS(SELECT 1 FROM catalog_relationships AS relationship WHERE relationship.relationship_id=NEW.relationship_id AND relationship.origin IN ('user','derived') AND (NOT ((relationship.origin='user' AND EXISTS(SELECT 1 FROM manual_catalog_relationships AS payload WHERE payload.relationship_id=relationship.relationship_id) AND NOT EXISTS(SELECT 1 FROM inferred_catalog_relationships AS payload WHERE payload.relationship_id=relationship.relationship_id) AND NOT EXISTS(SELECT 1 FROM reported_catalog_relationships AS payload WHERE payload.relationship_id=relationship.relationship_id)) OR (relationship.origin='derived' AND EXISTS(SELECT 1 FROM inferred_catalog_relationships AS payload WHERE payload.relationship_id=relationship.relationship_id) AND NOT EXISTS(SELECT 1 FROM manual_catalog_relationships AS payload WHERE payload.relationship_id=relationship.relationship_id) AND NOT EXISTS(SELECT 1 FROM reported_catalog_relationships AS payload WHERE payload.relationship_id=relationship.relationship_id))) OR (relationship.origin='user' AND EXISTS(SELECT 1 FROM manual_catalog_relationships AS payload WHERE payload.relationship_id=relationship.relationship_id AND NOT EXISTS(SELECT 1 FROM catalog_relationship_targets AS target WHERE target.target_id=payload.from_target_id AND ((SELECT count(*) FROM catalog_set_targets AS subtype WHERE subtype.target_id=payload.from_target_id) + (SELECT count(*) FROM catalog_media_entry_targets AS subtype WHERE subtype.target_id=payload.from_target_id) + (SELECT count(*) FROM no_intro_archive_targets AS subtype WHERE subtype.target_id=payload.from_target_id) + (SELECT count(*) FROM shared_file_targets AS subtype WHERE subtype.target_id=payload.from_target_id) + (SELECT count(*) FROM declared_hash_targets AS subtype WHERE subtype.target_id=payload.from_target_id) + (SELECT count(*) FROM observed_content_hash_targets AS subtype WHERE subtype.target_id=payload.from_target_id) + (SELECT count(*) FROM unresolved_catalog_targets AS subtype WHERE subtype.target_id=payload.from_target_id) + (SELECT count(*) FROM external_catalog_targets AS subtype WHERE subtype.target_id=payload.from_target_id))=1 AND (target.target_kind='catalog_set' AND EXISTS(SELECT 1 FROM catalog_set_targets AS typed JOIN catalog_sets AS owner ON owner.set_id=typed.set_id JOIN catalog_set_groups AS groups ON groups.set_group_id=owner.set_group_id JOIN catalog_source_elements AS element ON element.source_element_id=owner.set_id JOIN candidate_native_owners AS native ON native.source_element_id=owner.set_id AND native.element_kind=element.element_kind JOIN published_catalog_editions AS publication ON publication.edition_id=groups.edition_id WHERE typed.target_id=payload.from_target_id AND element.edition_id=groups.edition_id AND native.element_kind IN ('clrmamepro_set','logiqx_game','mame_machine','no_intro_dat_game','no_intro_export_game','no_intro_pc_game','software_item') AND (SELECT count(*) FROM candidate_native_owners AS actual WHERE actual.source_element_id=owner.set_id AND actual.element_kind<>'common_set_placement')=1) OR target.target_kind='catalog_media_entry' AND EXISTS(SELECT 1 FROM catalog_media_entry_targets AS typed JOIN catalog_media_entries AS owner ON owner.media_entry_id=typed.media_entry_id JOIN catalog_source_elements AS element ON element.source_element_id=owner.media_entry_id JOIN candidate_native_owners AS native ON native.source_element_id=owner.media_entry_id AND native.element_kind=element.element_kind JOIN published_catalog_editions AS publication ON publication.edition_id=element.edition_id WHERE typed.target_id=payload.from_target_id AND native.element_kind IN ('clrmamepro_rom','clrmamepro_sample','logiqx_disk','logiqx_rom','logiqx_sample','mame_disk','mame_rom','mame_sample','no_intro_dat_rom','no_intro_export_release_file','no_intro_export_source_file','no_intro_pc_rom','software_disk_entry','software_